function render(){readRoute();const p=route.page;const isLeite=tabs.some(t=>t[0]===p);$('#tabs').hidden=!isLeite;$('#tabs').innerHTML=tabs.map(([id,label])=>`<a href="${href(id)}" class="${id===p?'active':''}" ${id===p?'aria-current="page"':''}>${icon(id)}${label}</a>`).join('');$$('aside nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+p||(isLeite&&a.id==='nav-leite')));$('#sidebar').classList.remove('open');$('#content').classList.toggle('standalone',!isLeite);const labels={configuracoes:'Configurações de produção',relatorios:'Relatórios pecuários',importacao:'Conferir importação',estados:'Estados da prévia',rebanho:'Rebanho',nutricao:'Nutrição',animal:'Ficha do animal'};$('#page-title').textContent=labels[p]||'Leite';$('#page-description').textContent=isLeite?'A rotina do leite, da ordenha ao destino.':({configuracoes:'Regras e equipamentos com histórico preservado.',relatorios:'Consultas, exportações e documentos emitidos.',importacao:'Revise os fatos históricos antes de qualquer importação.',estados:'Cenários de apresentação isolados da rotina.',rebanho:'Animais e acesso ao histórico individual.',nutricao:'Dietas, fornecimentos e referência do leite.',animal:'Produção e qualidade no histórico individual.'}[p]||'');$('#page-actions').innerHTML='';
 let html; if(state.scenario==='sem-sitio'&&isLeite) html=`<div class="empty"><h3>Selecione um sítio</h3><p>Ordenhas e saldos precisam de um sítio para consulta e registro.</p>${button('Selecionar Fazenda Rio Novo','recover','','primary')}</div>`;else if(state.scenario==='carregando'&&isLeite)html='<div aria-live="polite" class="loading"><p>Carregando dados do leite…</p><span></span><span></span><span></span></div>'+button('Concluir carregamento simulado','recover');else if(state.scenario==='erro'&&isLeite)html=`<div class="empty"><h3>Não foi possível carregar os registros</h3><p>A consulta falhou. Seu rascunho continua disponível.</p>${button('Tentar novamente','recover','','primary')}</div>`;else {const pages={ordenhas:ordenhas,producao:producao,estoque:estoque,coletas:coletas,qualidade:qualidade,vendas:vendas,destinos:destinos,configuracoes:configuracoes,relatorios:relatorios,importacao:importacao,estados:estados,rebanho:rebanho,nutricao:nutricao,animal:animal};html=(pages[p]||ordenhas)();}$('#content').innerHTML=html;}
function parcelContext(d){const delta=Math.round((new Date(d.date+'T12:00:00')-new Date('2026-10-24T12:00:00'))/86400000),rule=configAt(d.date);return {withholding:animals.filter(a=>underWithholding(a.id,d.date)),births:delta>=0&&(rule.colostrum==='janela'?delta<rule.days:delta===0)?[{animal:'422',birth:'P088',date:'2026-10-24'}]:[]};}
function partHasData(p){return p.liters!==''||p.mm!=='';}
function partHasBasis(nature,d,p=d.parts[nature]){const context=parcelContext(d);return nature==='Comercial'||(nature==='Descarte'?context.withholding.some(a=>p.origins.includes(a.id)):context.births.some(b=>p.origins.includes(b.animal)));}
function visiblePart(nature,d){const p=d.parts[nature],ctx=parcelContext(d);return nature==='Comercial'||partHasData(p)||p.historical||p.manual||p.expanded&&(nature==='Descarte'?ctx.withholding.length:ctx.births.length)>0;}
function parcelActions(d,confirmed){if(confirmed)return '';const ctx=parcelContext(d);return `<div class="parcel-suggestions section">${ctx.withholding.length&&!visiblePart('Descarte',d)?button('Registrar descarte · '+ctx.withholding.length+' '+(ctx.withholding.length===1?'animal em carência':'animais em carência'),'expand-part','Descarte'):''}${ctx.births.length&&!visiblePart('Colostro',d)?button('Registrar colostro · '+ctx.births.length+' '+(ctx.births.length===1?'parto':'partos'),'expand-part','Colostro'):''}${button('Adicionar registro com justificativa','add-justified-part')}</div>`;}
function justifiedPartForm(preferred='Descarte'){captureDraft();modal('Adicionar registro com justificativa',`<div class="fields">${select('nature','Natureza',['Descarte','Colostro'],preferred)}<label class="full">Justificativa obrigatória<textarea name="justification" required></textarea></label></div><p class="section">Declaração direta: não cria carência, parto ou liberação comercial.</p>`,v=>{if(!v.justification?.trim())return fail('Informe a justificativa do registro direto.');const d=draft(),p=d.parts[v.nature];if(!partHasData(p)&&!partHasBasis(v.nature,d,p))p.origins=[];p.manual=true;p.expanded=true;p.justification=v.justification.trim();d.dirty=true;render();toast('Parcela adicionada como declaração com justificativa.');},'Adicionar parcela');}
function draftKey(){return q('medicao')?'registro|'+q('medicao'):'rascunho|'+q('rascunho','novo');}
function draft(){const key=draftKey();if(!state.drafts[key]){const m=state.measurements.find(m=>m.id===q('medicao')),day=m?.date||q('data',TODAY),parts={};for(const nature of milkNatures){const existing=m?measureParts(m).find(p=>p.nature===nature):null;parts[nature]={liters:existing?.liters??'',mm:existing?.mm??'',tankId:existing?.tankId||(existing?state.tanks.find(t=>t.name===existing.container)?.id||'outro':nature==='Comercial'?'t1':'outro'),tankSnapshot:existing?.tankSnapshot||null,container:existing?.container||(nature==='Comercial'?'Tanque principal':nature==='Descarte'?'Recipiente segregado de descarte':'Recipiente exclusivo de colostro'),origins:existing&&Array.isArray(existing.origins)?[...existing.origins]:nature==='Colostro'?['422']:nature==='Descarte'?['204']:animals.filter(a=>a.eligible&&a.del>0&&!underWithholding(a.id,day)).map(a=>a.id),first:!!existing?.first,expanded:!!existing||nature==='Comercial',historical:!!existing,manual:!!existing?.manual,justification:existing?.justification||''};}state.drafts[key]={id:m?.id||null,date:day,contextDate:day,turn:m?.turn||configAt(day).turns[Number(q('turno',0))]||configAt(day).turns[0],parts,status:m?.status||'Rascunho',saved:!!m,dirty:false,unassigned:m?measureParts(m).filter(p=>!p.nature).reduce((n,p)=>n+p.liters,0):0};}return state.drafts[key];}
function captureDraft(){const f=$('#ordenha-form');if(!f)return;const d=draft(),v=serialize(f);d.date=v.date??d.date;d.turn=v.turn??d.turn;for(const nature of milkNatures){const part=d.parts[nature];part.liters=v['liters_'+nature]??part.liters;part.mm=v['mm_'+nature]??part.mm;part.tankId=v['tank_'+nature]??part.tankId;part.container=part.tankId==='outro'?(v['container_'+nature]??part.container):(state.tanks.find(t=>t.id===part.tankId)?.name||part.container);part.justification=v['justification_'+nature]??part.justification;}}
function currentTank(){return state.tanks.find(t=>t.id===q('tanque','t1'))||state.tanks[0];}
function orderConsultation(){const rows=filterRows(state.measurements.map(m=>({...m,natures:measureParts(m).map(p=>p.nature)})));const pending=Object.entries(state.drafts).sort(([a],[b])=>a===state.lastOrderDraftKey?-1:b===state.lastOrderDraftKey?1:0).find(([key,d])=>d.status!=='Confirmada'&&(d.dirty||d.saved));return `<div class="sectionhead"><h2>Ordenhas registradas</h2><div class="actions">${pending?button('Retomar rascunho','resume-register',pending[0]):''}${button('Registrar ordenha','new-register','','primary')}</div></div>${toolbar('Buscar data, ordenha ou registro')}${table(['Data','Ordenha','Comercial (L)','Descarte (L)','Colostro (L)','Total (L)','Situação','Ação'],rows.map(m=>[date(m.date),m.turn,...milkNatures.map(n=>{const ps=measureParts(m).filter(p=>p.nature===n);return ps.length?fmt(ps.reduce((sum,p)=>sum+p.liters,0)):'—';}),fmt(measureParts(m).reduce((n,p)=>n+p.liters,0)),badge(measureParts(m).some(p=>!p.nature)?'Classificação pendente':m.status),button(m.status==='Confirmada'?'Consultar':'Editar registro','open-measure',m.id,'small')]),'Ordenhas')}`;}
function ordenhas(){const mode=q('modo','geral');if(mode==='registro')return orderRegistration();const html=subnav([['geral','Ordenhas registradas'],['individual','Controle individual mensal']],mode);return html+(mode==='individual'?individual():orderConsultation());}
function orderRegistration(){const d=draft(),confirmed=d.status==='Confirmada',total=milkNatures.reduce((n,k)=>n+Number(d.parts[k].liters||0),0),disabled=confirmed?'disabled':'';state.lastOrderDraftKey=draftKey();return `<div class="sectionhead"><div><h2>${confirmed?'Consultar ordenha':'Registrar ordenha'}</h2><p>${d.id?esc(d.id)+' · ':''}${badge(d.status)}</p></div>${button('Voltar à consulta','back-orders')}</div><form id="ordenha-form"><div class="fields">${input('date','Data da ordenha',d.date,'date','required data-record-date '+disabled)}${select('turn','Ordenha',configAt(d.date).turns,d.turn,'required '+disabled)}</div>${d.unassigned?`<div class="notice">${fmt(d.unassigned)} L da medição anterior ainda sem classificação. Informe manualmente as parcelas e suas origens físicas.</div>`:''}${d.contextDate!==d.date?'<div class="notice">Data alterada. As parcelas preenchidas foram preservadas; confira o contexto e justifique aquelas sem carência ou parto compatível.</div>':''}${parcelActions(d,confirmed)}<div class="milk-parts section">${milkNatures.filter(n=>visiblePart(n,d)).map(nature=>{const p=d.parts[nature];return `<fieldset class="milk-part"><legend>${nature}</legend>${p.manual?'<p class="parcel-declaration">Registro direto com justificativa</p>':''}<div class="fields">${select('tank_'+nature,'Tanque ou recipiente', [...state.tanks.map(t=>[t.id,t.name+' · v'+t.version]),['outro','Outro recipiente segregado']],p.tankId,'data-part-tank '+disabled)}${input('mm_'+nature,'Régua (mm) — opcional',p.mm,'number','min="0" step="0.1" '+disabled)}${input('liters_'+nature,'Volume informado manualmente (L)',p.liters,'number','min="0" step="0.001" '+disabled)}<div class="other-container" ${p.tankId!=='outro'?'hidden':''}>${input('container_'+nature,'Identificação do recipiente segregado',p.container,'text',disabled)}</div><div class="origin-summary"><span>Animais identificados</span><strong>${p.origins.map(id=>{const a=animals.find(a=>a.id===id);return esc(id+' · '+a.name)+(underWithholding(id,d.date)?' <span class="badge warn">Em carência</span>':'');}).join(', ')||'Nenhum'}</strong>${button(confirmed?'Consultar animais':'Conferir animais','origins',nature,'small')}</div></div>${nature==='Colostro'&&partHasBasis(nature,d,p)&&!p.manual?`<div class="colostrum-note">Canela · DEL 0 · parto P088 em 24/10/2026. ${configAt(d.date).colostrum==='primeira'?(p.first?'Primeira ordenha declarada.':'Confirme a primeira ordenha no detalhe dos animais.'):'Janela pós-parto: '+configAt(d.date).days+' dias.'}</div>`:''}${nature!=='Comercial'&&(p.manual||partHasData(p)&&!partHasBasis(nature,d,p))?`<label class="field section">Justificativa ${!partHasBasis(nature,d,p)?'obrigatória · sem contexto compatível':'do registro direto'}<textarea name="justification_${nature}" required ${disabled}>${esc(p.justification)}</textarea></label>`:''}</fieldset>`;}).join('')}</div><div class="sectionhead order-summary"><div><small>Total informado em litros</small><strong id="order-total">${fmt(total)} L</strong></div><p>Régua e litros descrevem o mesmo volume. A régua não converte nem soma litros.</p></div><div id="ordenha-error" role="alert" class="error-text"></div><div class="form-actions">${button('Voltar à consulta','back-orders')}${button(confirmed?'Consultar confirmação':'Guardar rascunho','save-measure')}${confirmed?button('Registrar outra ordenha','new-register','','primary'):button('Confirmar no estoque','confirm-measure','','primary')}</div></form>`;}

function individual(){const ids=Object.keys(state.individual);const rows=ids.map(id=>{const a=animals.find(x=>x.id===id),values=state.individual[id];return [button(a.id,'animal',id,'small'),a.name,...values.map((v,i)=>`<input aria-label="${a.name} · ${state.individualTurns[i]} (L)" type="number" min="0" step="0.1" style="width:85px" data-ind="${id}" data-turn="${i}" value="${v??''}" ${state.indConfirm?'disabled':''}>`),fmt(values.reduce((s,n)=>s+Number(n||0),0))+' L'];});return `<div class="sectionhead"><div><h2>Controle individual</h2><p>Aferição de outubro de 2026 · intervalo de ${state.config.interval} ${state.config.intervalUnit.toLowerCase()}.</p></div><input type="date" aria-label="Dia do controle individual" data-query="individualData" value="${q('individualData',TODAY)}"></div>${table(['Brinco','Nome',...state.individualTurns.map(t=>esc(t)+' (L)'),'Total'],state.scenario==='vazio'?[]:rows,'Animais',true)}<div class="form-actions">${button('Incluir animal','include-animal')}${button('Salvar controle','save-individual')}${button('Conferir entrada individual','confirm-individual','','primary')}</div><p class="section">Controle com três ordenhas · configuração v2 preservada. Fonte vigente: ${esc(state.config.source)}.</p>`;}
function productionSelection(){const mode=q('modo','dia'),all=state.measurements.filter(m=>m.date>=q('de','2026-10-01')&&m.date<=q('ate',TODAY)),parts=all.flatMap(m=>measureParts(m).map(part=>({m,part,liters:Number(part.liters),nature:part.nature}))),selected=parts.filter(p=>(!q('natureza')||p.nature===q('natureza'))&&(!q('classificacao')||(p.nature?'Declarada':'Pendente')===q('classificacao'))),days=[...new Set([...all.map(m=>m.date),...((TODAY>=q('de','2026-10-01')&&TODAY<=q('ate',TODAY))?[TODAY]:[])])];let rows=days.map(day=>{const original=all.filter(m=>m.date===day),ps=selected.filter(p=>p.m.date===day),missing=Math.max(0,configAt(day).turns.length-new Set(original.map(m=>m.turn)).size),pending=ps.filter(p=>!p.nature).reduce((n,p)=>n+p.liters,0),turnVolumes=Object.fromEntries(configAt(day).turns.map(turn=>[turn,ps.some(p=>p.m.turn===turn)?ps.filter(p=>p.m.turn===turn).reduce((n,p)=>n+p.liters,0):null]));return {id:day,date:day,name:date(day),liters:ps.reduce((n,p)=>n+p.liters,0),status:missing?'Parcial':'Completa',turnVolumes,natures:[...new Set(ps.map(p=>p.nature))],classification:q('classificacao')||(pending?'Pendente':'Declarada'),missing:missing?missing+' sem aferição':'Completa',pending:pending?fmt(pending)+' L':'Sem pendência',ruleVersion:configAt(day).version};}).filter(r=>(!q('natureza')&&!q('classificacao'))||selected.some(p=>p.m.date===r.date));if(mode==='mes'){rows=[...new Set(rows.map(r=>r.date.slice(0,7)))].map(month=>{const ds=rows.filter(r=>r.date.startsWith(month)),ps=selected.filter(p=>p.m.date.startsWith(month)),pending=ps.filter(p=>!p.nature).reduce((n,p)=>n+p.liters,0),turns=[...new Set(ds.flatMap(r=>Object.keys(r.turnVolumes)))],turnVolumes=Object.fromEntries(turns.map(turn=>[turn,ps.some(p=>p.m.turn===turn)?ps.filter(p=>p.m.turn===turn).reduce((n,p)=>n+p.liters,0):null]));return {id:month,date:ds.map(r=>r.date).sort().at(-1),name:new Date(month+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'}),liters:ps.reduce((n,p)=>n+p.liters,0),status:'Parcial',turnVolumes,natures:[...new Set(ps.map(p=>p.nature))],classification:q('classificacao')||(pending?'Pendente':'Declarada'),missing:'Cobertura parcial',pending:pending?fmt(pending)+' L':'Sem pendência'};});}const filtered=filterRows(rows),visibleParts=selected.filter(p=>filtered.some(r=>mode==='mes'?p.m.date.startsWith(r.id):p.m.date===r.id));return {mode,rows:filtered,visibleParts,visibleMeasures:[...new Set(visibleParts.map(p=>p.m))]};}
function producao(){const selection=productionSelection(),{mode,rows,visibleParts}=selection,turns=[...new Set(rows.flatMap(r=>Object.keys(r.turnVolumes)))];return `<div class="sectionhead"><h2>Produção geral</h2>${button('Sobre esta leitura','help-production')}</div>${facts([['Volume informado',fmt(visibleParts.reduce((n,p)=>n+p.liters,0))+' L'],['Sem classificação',fmt(visibleParts.filter(p=>!p.nature).reduce((n,p)=>n+p.liters,0))+' L'],['Agrupamento',mode==='mes'?'Por mês':'Por dia']])}${toolbar('Buscar data ou situação')}${table([mode==='mes'?'Mês':'Dia',...turns.map(t=>esc(t)+' (L)'),'Total (L)','Cobertura','Classificação','Ação'],rows.map(r=>[r.name,...turns.map(t=>r.turnVolumes[t]==null?'—':fmt(r.turnVolumes[t])),fmt(r.liters),badge(r.missing),r.pending,button('Ver detalhe','production-detail',r.id,'small')]),'Períodos')}<div class="production-costs section"><div class="sectionhead"><h2>Custos de produção</h2><span class="muted">Mesmo recorte de produção</span></div>${costsContent(selection)}</div>`;}

function estoque(){const orig=state.origins;const total=orig.reduce((s,o)=>s+o.remaining,0);const byNature=n=>orig.filter(o=>o.nature===n).reduce((s,o)=>s+o.remaining,0);const rows=Object.values(orig.reduce((acc,o)=>{const key=o.product+'|'+o.nature;if(!acc[key])acc[key]={id:o.id,product:o.product,nature:o.nature,liters:0,costKnown:true,value:0,ids:[]};acc[key].liters+=o.remaining;acc[key].value+=o.remaining*(o.cost||0);acc[key].costKnown&&=o.cost!==null;acc[key].ids.push(o.id);return acc;},{}));const filtered=filterRows(rows);return `<div class="sectionhead"><h2>Saldo de leite</h2><div class="actions">${button('Sobre o saldo','help-stock')}${button('Movimentos compartilhados','shared-stock')}</div></div>${facts([['Físico confirmado',fmt(total)+' L'],['Comercial identificado',fmt(byNature('Comercial'))+' L'],['Descarte',fmt(byNature('Descarte'))+' L'],['Colostro',fmt(byNature('Colostro'))+' L']])}<div class="notice">Classificação pendente: <strong>${fmt(byNature(''))} L</strong>. Disponibilidade comercial completa não aferível enquanto houver histórico sem natureza comprovada.</div>${toolbar('Buscar produto ou natureza',{period:false})}${table(['Produto','Natureza','Classificação','Saldo físico (L)','Custo','Ação'],filtered.map(r=>[r.product,r.nature?badge(r.nature||'Não informada'):'—',badge(r.nature?'Declarada':'Classificação pendente'),fmt(r.liters),r.costKnown?money(r.value):money(null),button('Origens e saídas','stock-detail',r.id,'small')]),'Produtos')}<div class="section"><h3>Medições ainda não confirmadas</h3>${table(['Data','Ordenha','Natureza','Volume (L)','Situação','Ação'],state.measurements.filter(m=>m.status!=='Confirmada').flatMap(m=>measureParts(m).map(p=>[date(m.date),m.turn,p.nature||'Não informada',fmt(p.liters),badge(p.nature?'Aguardando confirmação':'Classificação pendente'),button('Conferir','open-measure',m.id,'small')])),'Medições',true)}</div>`;}
function coletas(){const rows=filterRows(state.collections);return `<div class="sectionhead"><h2>Coletas físicas</h2><div class="actions">${button('Rotina de coleta','routine')}${button('Registrar retirada','new-collection','','primary')}</div></div>${toolbar('Buscar comprador, coleta ou romaneio')}${table(['Data física','Coleta','Comprador','Retirado (L)','Preço','Ação'],rows.map(r=>[date(r.date),r.id,r.buyer,fmt(r.liters),badge(r.status),button('Ver coleta','collection-detail',r.id,'small')]),'Coletas')}<div class="section">${lines([['Rotina',state.routine.active?`A cada ${state.routine.frequency} dias · ${esc(state.routine.buyer)}`:'Inativa'],['Próxima previsão',date(state.routine.next)]])}<p>Previsão de rotina: não cria retirada, venda, alerta ou movimento automático.</p></div>`;}
function qualidade(){const mode=q('modo','amostras');const sampleRows=filterRows(state.samples);let body;if(mode==='resultados'){const param=state.parameters.find(p=>p.id===q('parametro','gordura'))||state.parameters[0];const subject=q('sujeito','Tanque principal');const list=sampleRows.filter(s=>s.subject===subject&&s.values[param.id]!=null&&s.format===q('formato','Leolac completo')&&s.status!=='Anulada');body=`<div class="inline-controls sectionhead"><label class="field">Parâmetro<select data-query="parametro">${state.parameters.map(p=>`<option value="${p.id}" ${p.id===param.id?'selected':''}>${p.name} (${p.unit})</option>`).join('')}</select></label><label class="field">Origem da série<select data-query="sujeito">${[...new Set(state.samples.map(s=>s.subject))].map(s=>`<option ${s===subject?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label class="field">Formato e método<select data-query="formato">${state.formats.map(f=>`<option>${esc(f.name)}</option>`).join('')}</select></label></div>${toolbar('Buscar amostra ou data')}${table(['Amostra','Data da amostra',param.name+' ('+param.unit+')','Formato','Método','Ação'],list.map(s=>[s.id,date(s.date),fmt(s.values[param.id]),esc(s.format)+' · v1',esc(s.method),button('Laudo completo','sample-detail',s.id,'small')]),'Resultados')}<p class="section">Uma série por parâmetro, unidade, formato, método e origem. Sem médias ou conversões entre laudos.</p>`;}else body=toolbar('Buscar amostra, animal ou tanque')+table(['Data da amostra','Identificação','Origem','Tipo','Situação','Ação'],sampleRows.map(s=>[date(s.date),s.id,esc(s.subject),s.kind,badge(s.status),button('Laudo completo','sample-detail',s.id,'small')]),'Amostras');return `${subnav([['amostras','Amostras'],['resultados','Resultados']],mode)}<div class="sectionhead"><h2>Qualidade do leite</h2><div class="actions">${button('Formatos de laudo','formats')}${button('Registrar amostra','new-sample','','primary')}</div></div>${body}`;}
function vendas(){const rows=filterRows(state.sales.map(s=>({...s,date:s.end})));return `<div class="sectionhead"><h2>Vendas de leite</h2><div class="actions">${button('Nova operação por período','new-operation')}${button('Venda avulsa','new-sale','','primary')}</div></div>${toolbar('Buscar comprador ou operação',{de:'2026-08-01',ate:'2026-10-31'})}${table(['Operação','Comprador','Período','Modalidade','Situação','Ação'],rows.map(s=>[s.id,esc(s.buyer),`${date(s.start)} a ${date(s.end)}`,s.kind,badge(s.status),button('Abrir operação','sale-detail',s.id,'small')]),'Vendas')}`;}
function destinos(){return `<div class="sectionhead"><h2>Alimentação e descarte</h2><div class="actions">${button('Descarte físico','new-discard')}${button('Registrar fornecimento','new-feed','','primary')}</div></div>${toolbar('Buscar destino, origem ou fornecimento')}${table(['Data','Registro','Natureza','Destino','Volume (L)','Situação','Ação'],filterRows(state.destinations).map(d=>[date(d.date),d.id,badge(d.nature),esc(d.destination),fmt(d.liters),badge(d.status),button('Ver detalhe','destination-detail',d.id,'small')]),'Destinações')}<p class="section">Comercial, descarte e colostro são naturezas. Alimentação e eliminação física são destinos distintos.</p>`;}
function configuracoes(){const c=state.config;return `<div class="sectionhead"><h2>Produção</h2>${badge('Versão '+c.version+' · desde '+date(c.effective))}</div><div class="configrows"><div><strong>Ordenhas do dia</strong><span>${c.turns.map(esc).join(' · ')}</span>${button('Editar ordenhas','config-turns')}</div><div><strong>Controle individual</strong><span>A cada ${c.interval} ${c.intervalUnit.toLowerCase()} · fonte ${c.source.toLowerCase()}</span>${button('Editar controle','config-individual')}</div><div><strong>Critério de colostro</strong><span>${c.colostrum==='primeira'?'Primeira ordenha comprovada':`Janela pós-parto de ${c.days} dias`}</span>${button('Configurar colostro','config-colostrum')}</div></div><div class="sectionhead section"><h2>Tanques e calibração</h2>${button('Cadastrar tanque','new-tank')}</div>${table(['Tanque','Capacidade (L)','Modelo','Série','Versão','Ação'],state.tanks.map(t=>[esc(t.name),fmt(t.capacity,0),esc(t.model),esc(t.serial),'v'+t.version,button('Equipamento e tabela','tank-detail',t.id,'small')]),'Tanques',true)}<div class="section"><h3>Vigências e histórico</h3>${table(['Vigência','Versão','Decisão','Autoria'],[...state.configHistory.map(r=>[date(r.effective),'v'+r.version,esc(r.reason),esc(r.author)])],'Versões',true)}<p>Novas versões não reclassificam fatos antigos. Sem regra ou evidência histórica comprovada, o registro conserva a pendência.</p></div>`;}
function relatorios(){return `<div class="sectionhead"><h2>Leite</h2>${button('Emitir documento','report-form','','primary')}</div><div class="configrows"><div><strong>Produção por dia ou mês</strong><span>Volumes, cobertura e classificação</span>${button('Exportar CSV','export-report','producao')}</div><div><strong>Origens e destinos</strong><span>Rastreabilidade do estoque compartilhado</span>${button('Exportar CSV','export-report','estoque')}</div><div><strong>Resultados de qualidade</strong><span>Parâmetro e unidade preservados</span>${button('Exportar CSV','export-report','qualidade')}</div><div><strong>Comercial e custos</strong><span>Períodos, documentos e cobertura de custo</span>${button('Exportar CSV','export-report','comercial')}</div></div><div class="sectionhead section"><h3>Documentos emitidos</h3></div>${table(['Documento','Emissão','Período','Tipo','Versão','Ação'],state.snapshots.map(s=>[s.id,date(s.date),esc(s.period),esc(s.kind),'v'+s.version,button('Consultar snapshot','snapshot-detail',s.id,'small')]),'Documentos',true)}`;}
function importacao(){return `<div class="sectionhead"><h2>Prévia histórica</h2>${badge('Sem gravação')}</div><form id="import-form"><div class="fields">${input('file','Arquivo para conferência','','file','accept=".csv,.json,.xlsx"')}${select('source','Origem',['IDEAGRI · carga inicial','Planilha histórica'],'IDEAGRI · carga inicial')}</div><div class="form-actions">${button('Usar exemplo demonstrativo','import-preview','','primary')}</div></form><div id="import-preview"></div><p class="section">Esta ferramenta confere a origem dos fatos. Nenhum arquivo é enviado; não cria sincronização nem grava registros.</p>`;}
function estados(){return `<div class="sectionhead"><h2>Cenários de apresentação</h2>${button('Restaurar consulta normal','recover','','primary')}</div><p>Escolha um cenário e abra a rotina indicada. Os dados sintéticos salvos nesta sessão serão preservados.</p><div class="configrows">${[['carregando','Carregando','Cabeçalho e navegação preservados'],['vazio','Vazio real','Consulta sem registros'],['erro','Falha recuperável','Repetir consulta preserva rascunho'],['sem-sitio','Sem sítio','Registro pede um sítio autorizado'],['ocultos','Valores ocultos','Quantidades visíveis; custos e preços mascarados'],['historico','Histórico pendente','Quantidade conhecida, natureza e custo sem comprovação']].map(([id,l,d])=>`<div><strong>${l}</strong><span>${d}</span>${button('Visualizar cenário','scenario',id)}</div>`).join('')}</div>`;}
function rebanho(){return `<div class="sectionhead"><h2>Animais</h2>${badge('Recorte demonstrativo')}</div>${toolbar('Buscar brinco, nome ou lote',{period:false})}${table(['Brinco','Nome','Lote','Finalidade','DEL','Ação'],filterRows(animals.map(a=>({...a,status:'Ativo'}))).map(a=>[a.id,a.name,a.lot,'Leite',a.del??'Não comprovado',button('Abrir ficha','animal',a.id,'small')]),'Animais')}`;}
function nutricao(){return `<div class="sectionhead"><h2>Nutrição por lote</h2>${button('Fornecer leite','new-feed','','primary')}</div>${toolbar('Buscar lote ou dieta',{period:false})}${table(['Lote','Animais','Dieta vigente','Custo produtivo','Referência leite','Ação'],filterRows([{id:'B01',name:'Bezerreiro',date:TODAY}]).map(()=>['B01 · Bezerreiro','10','Aleitamento · v3',money(84),money(150)+' · provisória',button('Ver fornecimento','destination-detail','D031','small')]),'Lotes')}`;}
function animal(){const a=animals.find(a=>a.id===q('id','118'))||animals[0],mode=q('modo','producao');return `<div class="sectionhead"><div><h2>${a.id} · ${a.name}</h2><p>${a.lot} · finalidade Leite · DEL ${a.del??'não comprovado'}</p></div>${button('Voltar ao rebanho','goto','rebanho')}</div>${subnav([['producao','Produção'],['qualidade','Qualidade']],mode)}${mode==='qualidade'?table(['Amostra','Data','Situação','Ação'],state.samples.filter(s=>s.animal===a.id).map(s=>[s.id,date(s.date),badge(s.status),button('Laudo completo','sample-detail',s.id,'small')]),'Amostras',true):table(['Dia do controle','Manhã (L)','Tarde (L)','Noite (L)','Total (L)'],state.individual[a.id]?[[date(TODAY),...state.individual[a.id].map(v=>fmt(v)),fmt(state.individual[a.id].reduce((s,v)=>s+Number(v||0),0))]]:[],'Controles',true)}<div class="section"><h3>Contexto sanitário e de origem</h3>${lines([['Parto',a.del===0?'P088 · 24/10/2026':'Comprovado no histórico'],['Carência',a.id==='204'?'Conferida para demonstração':'Sem impedimento no recorte demonstrativo'],['Fonte geral','Não atribui litros do tanque a esta vaca']])}</div>`;}
function filters(){const fields=filterFields();modal('Filtros da consulta',`<div class="fields">${fields.map(([key,label,options])=>select(key,label,options,q(key,key==='modo'?'dia':''))).join('')}</div>${fields.length?'':'<p>Esta consulta é refinada pela busca e pelo período.</p>'}`,v=>{const changes=Object.fromEntries(filterKeys.filter(k=>k!=='modo'||route.page==='producao').map(k=>[k,null]));navigate(route.page,{...changes,...v,pagina:null});},'Aplicar filtros',button('Limpar rascunho','reset-filters'));}

function tankTable(id){const t=state.tanks.find(t=>t.id===id);modal(`${t.name} · calibração v${t.version}`,`${lines([['Capacidade nominal',fmt(t.capacity,0)+' L'],['Vigência',date(t.effective)],['Referência documental',esc(t.reference)]])}<div class="section">${table(['Régua (mm)','Volume exato (L)'],Object.entries(t.points).map(([mm,l])=>[mm,fmt(l)]),'Pontos de calibração',true)}</div><p class="section">Somente pontos cadastrados. Não há interpolação ou extrapolação. A capacidade nominal não determina a conversão.</p>`);}
function originsModal(nature='Comercial'){captureDraft();const d=draft(),part=d.parts[nature],col=nature==='Colostro',rule=configAt(d.date),direct=part.manual||!partHasBasis(nature,d,part)&&!!part.justification.trim(),list=col&&!direct?animals.filter(a=>a.id==='422'):animals.filter(a=>a.eligible&&(a.del>0||direct));modal('Animais de origem · '+nature,`<p>Os animais identificam a origem. Não há atribuição automática de litros por vaca.</p><div class="origins">${list.map(a=>{const blocked=nature==='Comercial'&&underWithholding(a.id,d.date);return `<label class="origin"><input type="checkbox" name="origin" value="${a.id}" ${part.origins.includes(a.id)?'checked':''} ${d.status==='Confirmada'||blocked?'disabled':''}><strong>${a.id} · ${a.name}</strong><span>DEL ${a.del}</span>${underWithholding(a.id,d.date)?badge('Em carência comercial'):''}</label>`;}).join('')}</div>${col&&!direct?`<div class="section">${lines([['Parto comprovado','P088 · 24/10/2026'],['Regra vigente',rule.colostrum==='primeira'?'Primeira ordenha':'Janela pós-parto: '+rule.days+' dias']])}${rule.colostrum==='primeira'?check('first','Declaro que esta parcela é a primeira ordenha de Canela após o parto P088.',part.first):'<p>DEL 0 está incluído na janela. A natureza não comprova liberação comercial.</p>'}</div>`:''}${direct?`<div class="notice">Declaração direta: ${esc(part.justification)}. Nenhum evento sanitário ou parto é criado ou presumido.</div>`:''}${nature==='Comercial'&&parcelContext(d).withholding.length?'<div class="notice">Animais em carência não podem compor a origem comercial.</div>':''}`,d.status==='Confirmada'?null:(v,form)=>{const selected=new FormData(form).getAll('origin');if(!selected.length&&!direct)return fail('Selecione ao menos uma origem.');if(col&&!direct&&rule.colostrum==='primeira'&&!v.first)return fail('Confirme a declaração de primeira ordenha.');if(nature==='Comercial'&&selected.some(id=>underWithholding(id,d.date)))return fail('Há animal em carência na origem comercial.');part.origins=selected;part.first=!!v.first;d.dirty=true;render();toast('Animais da parcela atualizados no rascunho.');},'Usar seleção');}

function draftParts(d){const parts=[];for(const nature of milkNatures){const p=d.parts[nature];if(p.liters===''&&p.mm==='')continue;if(p.liters===''||!Number.isFinite(Number(p.liters))||Number(p.liters)<0)throw new Error('Informe os litros manualmente na parcela '+nature+'. A régua não faz conversão.');if(p.mm!==''&&(!Number.isFinite(Number(p.mm))||Number(p.mm)<0))throw new Error('Confira a régua da parcela '+nature+'.');if(Number(p.liters)>0&&!p.container.trim())throw new Error('Identifique a origem física segregada da parcela '+nature+'.');const direct=nature!=='Comercial'&&(p.manual||!partHasBasis(nature,d,p));if(direct&&!p.justification.trim())throw new Error('Informe a justificativa da parcela '+nature+' sem contexto compatível ou declarada diretamente.');const tank=state.tanks.find(t=>t.id===p.tankId);if(tank&&Number(p.liters)>tank.capacity)throw new Error('A parcela '+nature+' excede a capacidade de '+fmt(tank.capacity,0)+' L do tanque cadastrado. Confira os litros manuais.');parts.push({nature,liters:Number(p.liters),mm:p.mm===''?'':Number(p.mm),container:tank?tank.name:p.container.trim(),tankId:p.tankId,tankSnapshot:tank?{id:tank.id,name:tank.name,version:tank.version,serial:tank.serial,capacity:tank.capacity}:null,origins:[...p.origins],first:p.first,manual:direct,justification:p.justification.trim(),declaration:direct?'DIRETA_JUSTIFICADA':'CONTEXTO_OPERACIONAL'});}if(!parts.length)throw new Error('Informe manualmente os litros de ao menos uma parcela. Zero precisa ser explícito.');return parts;}
function persistMeasure(d,parts,confirm){let m=state.measurements.find(m=>m.id===d.id);if(m?.status==='Confirmada')return m;if(!m){m={id:'M'+(++state.next)};state.measurements.push(m);d.id=m.id;}Object.assign(m,{date:d.date,turn:d.turn,parts:JSON.parse(JSON.stringify(parts)),liters:parts.reduce((n,p)=>n+p.liters,0),nature:parts.length===1?parts[0].nature:'',tank:'Várias origens segregadas',status:confirm?'Confirmada':'Salva'});if(confirm){for(const p of parts.filter(p=>p.liters>0)){if(state.origins.some(o=>o.measureId===m.id&&o.partKey===p.nature))continue;state.origins.push({id:'O'+(++state.next),measureId:m.id,partKey:p.nature,date:m.date,turn:m.turn,tank:p.container,tankId:p.tankId,tankSnapshot:p.tankSnapshot,product:p.nature==='Comercial'?'Leite resfriado':p.nature==='Colostro'?'Colostro':'Leite para uso interno',nature:p.nature,qty:p.liters,remaining:p.liters,cost:null,animals:[...p.origins],status:'Confirmada',ruleVersion:configAt(m.date).version,mm:p.mm,justification:p.justification,declaration:p.declaration});}}for(const p of parts)Object.assign(d.parts[p.nature],{manual:p.manual,justification:p.justification,expanded:true});d.status=m.status;d.saved=true;d.dirty=false;d.contextDate=d.date;d.unassigned=0;return m;}
function saveMeasure(confirm=false){captureDraft();const d=draft();if(d.status==='Confirmada')return measurementReceipt(d);let parts;try{parts=draftParts(d);}catch(e){$('#ordenha-error').textContent=e.message;return;}if(confirm){const positive=parts.filter(p=>p.liters>0),containers=positive.map(p=>p.tankSnapshot?'tanque:'+p.tankSnapshot.serial:p.container.toLocaleLowerCase('pt-BR'));if(new Set(containers).size!==containers.length){$('#ordenha-error').textContent='Naturezas diferentes exigem origens físicas distintas. Não divida por cálculo o leite já misturado.';return;}for(const p of positive){if(!p.origins.length&&!p.manual){$('#ordenha-error').textContent='Confira os animais de origem da parcela '+p.nature+'.';return;}if(p.nature==='Comercial'&&p.origins.some(id=>{const a=animals.find(a=>a.id===id);return !a?.eligible||!a.del||underWithholding(id,d.date);})){ $('#ordenha-error').textContent='Parcela comercial com origem sem elegibilidade ou em carência. Confira os animais.';return;}if(p.nature==='Colostro'&&!p.manual){const dayDelta=Math.round((new Date(d.date+'T12:00:00')-new Date('2026-10-24T12:00:00'))/86400000),rule=configAt(d.date);if(!p.origins.includes('422')||dayDelta<0||(rule.colostrum==='janela'&&dayDelta>=rule.days)){$('#ordenha-error').textContent='Confira a cria, o parto e a elegibilidade da origem de colostro na data.';return;}if(rule.colostrum==='primeira'&&!p.first){originsModal('Colostro');return;}}}}
 const save=()=>{persistMeasure(d,parts,confirm);render();toast(confirm?'Parcelas confirmadas uma vez em origens separadas do estoque.':'Rascunho guardado nesta sessão, sem entrada de estoque.');};if(!confirm)return save();modal('Confirmar parcelas no estoque',`${table(['Natureza','Origem física','Régua (mm)','Litros manuais'],parts.map(p=>[p.nature,esc(p.container)+(p.tankSnapshot?' · v'+p.tankSnapshot.version:''),p.mm===''?'—':fmt(p.mm),fmt(p.liters)]),'Parcelas',true)}${parts.filter(p=>p.justification).length?lines(parts.filter(p=>p.justification).map(p=>[p.nature+' · declaração direta',esc(p.justification)])):''}<div class="notice">Somente litros manuais compõem o total. Cada natureza mantém sua origem física segregada; leite já misturado não é dividido por rateio.</div>${check('declared','Conferi a segregação física, as naturezas e os animais de cada parcela.')}`,v=>{if(!v.declared)return fail('Confirme a segregação física antes de continuar.');save();},'Confirmar parcelas');}
function measurementReceipt(d){const origins=state.origins.filter(o=>o.measureId===d.id);modal('Confirmação da ordenha',`${lines([['Registro',esc(d.id)],['Situação',badge('Confirmada')],['Autoria','Equipe Rio Novo']])}<div class="section">${table(['Entrada','Natureza','Origem física','Litros','Justificativa'],origins.map(o=>[o.id,o.nature,esc(o.tank)+(o.tankSnapshot?' · v'+o.tankSnapshot.version:''),fmt(o.qty),esc(o.justification||'—')]),'Origens confirmadas',true)}</div><div class="section"><h3>Verificação da prévia</h3>${button('Testar reenvio sem nova entrada','retry-measure',d.id)}</div>`);}
function guardChange(changes){captureDraft();navigate('ordenhas',changes);}
function productionDetail(id){const {visibleParts}=productionSelection(),list=visibleParts.filter(p=>id.length===7?p.m.date.startsWith(id):p.m.date===id);modal('Produção · '+(id.length===7?new Date(id+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'}):date(id)),`${table(['Ordenha','Natureza','Origem física','Régua (mm)','Litros manuais','Estado'],list.map(({m,part})=>[m.turn,part.nature||badge('Classificação pendente'),esc(part.container)+(part.tankSnapshot?' · v'+part.tankSnapshot.version:''),part.mm===''?'—':fmt(part.mm),fmt(part.liters),badge(m.status)]),'Parcelas',true)}<p class="section">Régua e litros descrevem o mesmo volume; somente os litros manuais são totalizados.</p><div class="section">${button('Consultar ordenhas deste dia','open-day',id.length===7?TODAY:id)}</div>`);}
function costSummary(selection){const recorteSemVinculo=!!q('natureza')||!!q('classificacao');const facts=[{date:'2026-10-23',component:'Nutrição',amount:1180},{date:'2026-10-23',component:'Sanidade',amount:200}];const selected=recorteSemVinculo?[]:facts.filter(f=>f.date>=q('de','2026-10-01')&&f.date<=q('ate',TODAY));return {facts:selected,total:selected.reduce((n,f)=>n+f.amount,0),semVinculo:recorteSemVinculo};}
function costsContent(selection=productionSelection()){const c=costSummary(selection);return `${table(['Classificação','Custo registrado'],c.facts.map(f=>[f.component,money(f.amount)]),'Custos registrados',true)}${lines([['Total conhecido',c.facts.length?money(c.total):money(null)],['Custo por litro',money(null)]])}<div class="notice">${c.semVinculo?'Custos sem vínculo comprovado com a natureza ou classificação selecionada.':'Custos de fontes fictícias independentes da valorização do estoque; a cobertura produtiva do exemplo é parcial.'} O custo completo permanece a apurar, sem rateio presumido.</div>`;}
function costs(){modal('Custos de produção',costsContent());}

function stockDetail(id){const o=state.origins.find(o=>o.id===id),group=state.origins.filter(x=>x.product===o.product&&x.nature===o.nature);modal(o.product+' · '+o.nature,`${lines([['Saldo confirmado',fmt(group.reduce((s,x)=>s+x.remaining,0))+' L'],['Localização física atual','Não apurada por tanque'],['Custo',group.some(x=>x.cost===null)?money(null):money(group.reduce((s,x)=>s+x.remaining*x.cost,0))]])}<div class="section"><h3>Origens</h3>${table(['Origem','Data','Ordenha','Entrada (L)','Remanescente (L)','Ação'],group.map(x=>[x.id,date(x.date),x.turn,fmt(x.qty),fmt(x.remaining),button('Ver origem','origin-detail',x.id,'small')]),'Origens',true)}</div><div class="section"><h3>Saídas vinculadas</h3>${table(['Fato','Destino','Quantidade (L)'],[...state.collections.filter(c=>(c.origins||[]).some(p=>group.some(g=>g.id===p.id))).map(c=>[c.id,'Coleta '+esc(c.buyer),fmt(c.origins.filter(p=>group.some(g=>g.id===p.id)).reduce((s,p)=>s+p.liters,0))]),...state.sales.filter(s=>(s.origins||[]).some(p=>group.some(g=>g.id===p.id))).map(s=>[s.id,'Venda avulsa '+esc(s.buyer),fmt(s.origins.filter(p=>group.some(g=>g.id===p.id)).reduce((n,p)=>n+p.liters,0))]),...state.destinations.filter(d=>d.origins.some(x=>group.some(g=>g.id===x.id))).map(d=>[d.id,esc(d.destination),fmt(d.origins.filter(x=>group.some(g=>g.id===x.id)).reduce((s,x)=>s+x.liters,0))])],'Saídas',true)}</div>`);}
function originDetail(id){const o=state.origins.find(o=>o.id===id);modal('Origem '+o.id,`${lines([['Produto',esc(o.product)],['Data e ordenha',date(o.date)+' · '+esc(o.turn)],['Equipamento na origem',esc(o.tank)],['Versão do tanque',o.tankSnapshot?'v'+o.tankSnapshot.version:state.tanks.find(t=>t.name===o.tank)?'v'+state.tanks.find(t=>t.name===o.tank).version:'Outro recipiente / não comprovada'],['Quantidade confirmada',fmt(o.qty)+' L'],['Remanescente',fmt(o.remaining)+' L'],['Natureza',o.nature?badge(o.nature):'Não informada'],['Classificação',badge(o.nature?'Declarada':'Classificação pendente')],['Custo por litro',money(o.cost)],['Regra histórica',o.status==='Histórico pendente'?'Não comprovada':'Snapshot da versão vigente'],['Animais',o.animals.length?o.animals.join(', '):o.justification?'Não informados · declaração justificada':'Sem evidência histórica'],['Declaração',o.declaration==='DIRETA_JUSTIFICADA'?'Registro direto com justificativa':'Contexto operacional / histórico'],['Justificativa',esc(o.justification||'—')]])}<div class="section actions">${o.cost===null?button('Apurar custo documentado','value-origin',o.id):''}${o.status==='Histórico pendente'?button('Conferir pendência','history-review',o.id):''}</div>`);}
function valueOrigin(id){const o=state.origins.find(o=>o.id===id);if(state.hidden)return toast('Apuração exige permissão para visualizar e registrar valores.');modal('Apurar custo · '+id,`<div class="fields">${input('total','Custo total documentado (R$)','','number','min="0.01" step="0.01" required')}${input('ref','Referência documental','','text','required')}<label class="full">Motivo<textarea name="reason" required></textarea></label></div><p class="section">O valor será apropriado à quantidade já consumida e ao saldo, sem nova quantidade, despesa ou caixa.</p>`,v=>{if(Number(v.total)<=0)return fail('Informe um custo positivo.');o.cost=Number(v.total)/o.qty;state.revisionLog.push({date:TODAY,version:1,reason:'Custo apurado · '+o.id+' · '+v.ref});render();toast('Custo apropriado às saídas e ao saldo, sem nova baixa.');},'Apurar custo');}
function historyReview(id){const o=state.origins.find(o=>o.id===id);modal('Histórico pendente · '+id,`${lines([['Quantidade conhecida',fmt(o.remaining)+' L'],['Natureza','Sem comprovação'],['Primeira ordenha','Sem evidência'],['Regra aplicada','Não comprovada']])}<p class="section">A nova regra de colostro não reclassifica este fato. Concilie os documentos históricos antes de uma regularização; esta prévia não inventa evidência retroativa.</p><div class="section">${button('Abrir conferência de importação','goto','importacao')}</div>`);}
function collectionDetail(id){const c=state.collections.find(x=>x.id===id);modal('Coleta '+id,`${lines([['Data física',date(c.date)],['Comprador',esc(c.buyer)],['Retirado',fmt(c.liters)+' L'],['Aceito pelo comprador',fmt(c.accepted)+' L'],['Diferença',fmt(c.liters-c.accepted)+' L'],['Romaneio',esc(c.receipt)],['Preço',badge(c.status)],['Operação comercial',c.op]])}<p class="section">A diferença de volume é uma conferência comercial. A baixa física permanece em ${fmt(c.liters)} L.</p><div class="section actions">${button('Abrir operação de venda','sale-detail',c.op)}${button('Conferir aceite','collection-accept',c.id)}</div>`);}
function collectionAccept(id){const c=state.collections.find(x=>x.id===id);modal('Aceite do comprador · '+id,`<div class="fields">${input('accepted','Volume aceito (L)',c.accepted,'number','min="0" step="0.001" required')}${input('document','Referência do aceite',c.receipt,'text','required')}<label class="full">Motivo da diferença<textarea name="reason" required>${c.liters!==c.accepted?'Diferença conferida no romaneio.':''}</textarea></label></div><p class="section">O aceite não refaz a retirada física.</p>`,v=>{const s=state.sales.find(s=>s.id===c.op);if(s.status==='Fechada')return fail('Operação fechada. Faça uma correção comercial versionada para alterar o aceite.');c.accepted=Number(v.accepted);c.receipt=v.document;s.accepted=true;render();toast('Aceite atualizado sem movimento de estoque.');},'Confirmar aceite');}
function operationOptions(){return state.sales.filter(s=>s.status==='Aberta').map(s=>[s.id,`${s.id} · ${s.buyer} · ${date(s.start)} a ${date(s.end)}`]);}
function newCollection(){modal('Registrar retirada física',`<div class="fields">${input('date','Data física',TODAY,'date','required')}${select('op','Operação por período',operationOptions(),'V026','required')}${input('liters','Volume retirado (L)','','number','min="0.001" step="0.001" required')}${input('receipt','Romaneio / comprovante','','text','required')}${input('accepted','Volume aceito (L) — opcional','','number','min="0" step="0.001"')}<div class="memo">Preço pendente. A operação permanece aberta até a negociação e o fechamento.</div></div>`,v=>{const op=state.sales.find(s=>s.id===v.op);if(!op)return fail('Crie uma operação aberta antes de registrar a retirada.');if(v.date<op.start||v.date>op.end)return fail('A retirada precisa estar dentro do período da operação.');const available=state.origins.filter(o=>o.nature==='Comercial').reduce((s,o)=>s+o.remaining,0);if(Number(v.liters)>available)return fail(`Saldo comercial conhecido insuficiente: ${fmt(available)} L.`);const portions=allocate(Number(v.liters),'Comercial');const id='C'+(++state.next);state.collections.unshift({id,date:v.date,buyer:op.buyer,liters:Number(v.liters),accepted:v.accepted===''?Number(v.liters):Number(v.accepted),origins:portions,op:op.id,status:'Preço pendente',receipt:v.receipt});render();toast('Retirada registrada uma vez. A operação comercial continua aberta.');},'Registrar retirada');}
function allocate(liters,nature){let remaining=liters;const portions=[];for(const o of state.origins.filter(o=>o.nature===nature).sort((a,b)=>a.date.localeCompare(b.date))){const qty=Math.min(o.remaining,remaining);if(qty>0){o.remaining-=qty;remaining-=qty;portions.push({id:o.id,liters:qty});}if(remaining<0.000001)break;}return portions;}
function routine(){const r=state.routine;modal('Rotina de coleta',`<div class="fields">${select('buyer','Comprador',['Leolac','Queijaria Boa Vista'],r.buyer)}${input('frequency','Intervalo previsto (dias)',r.frequency,'number','min="1" max="31" required')}${input('next','Próxima previsão',r.next,'date','required')}${check('active','Rotina ativa',r.active)}</div><div class="notice">É uma previsão operacional, sem alerta, venda ou coleta automática.</div>`,v=>{Object.assign(r,{buyer:v.buyer,frequency:Number(v.frequency),next:v.next,active:!!v.active});render();toast('Rotina atualizada nesta sessão.');});}
function newOperation(){modal('Nova operação por período',`<div class="fields">${input('buyer','Comprador','','text','required')}${input('start','Início do período','2026-11-01','date','required')}${input('end','Fim do período','2026-11-30','date','required')}${input('reference','Referência do acordo','','text')}</div>`,v=>{if(v.end<v.start)return fail('O fim deve ser igual ou posterior ao início.');if(state.sales.some(s=>s.status==='Aberta'&&s.buyer===v.buyer&&s.start<=v.end&&s.end>=v.start))return fail('Já existe operação aberta deste comprador neste período.');state.sales.unshift({id:'V'+(++state.next),buyer:v.buyer,start:v.start,end:v.end,kind:'Por período',status:'Aberta',price:null,quality:[],docs:[],finance:null,accepted:false,version:1});navigate('vendas',{de:v.start,ate:v.end});render();toast('Operação aberta. Registre as retiradas em Coletas.');},'Criar operação aberta');}
function saleLiters(s,accepted=false){return s.kind==='Avulsa'?s.liters:state.collections.filter(c=>c.op===s.id).reduce((sum,c)=>sum+(accepted?c.accepted:c.liters),0);}
function saleDetail(id){const s=state.sales.find(s=>s.id===id);if(!s)return toast('Operação não encontrada nesta prévia.');const cs=state.collections.filter(c=>c.op===id);const total=saleLiters(s),accepted=saleLiters(s,true);modal('Operação '+id+' · '+s.buyer,`${lines([['Situação',badge(s.status)],['Período',date(s.start)+' a '+date(s.end)],['Modalidade',s.kind],['Versão','v'+s.version],['Retirado fisicamente',fmt(total)+' L'],['Volume comercial aceito',fmt(accepted)+' L'],['Preço negociado',s.price===null?(state.hidden?money(0):'Pendente'):money(s.price)+'/L'],['Total comercial',s.price===null?(state.hidden?money(0):'Pendente'):money(accepted*s.price)],['Financeiro',s.finance||'Aguardando fechamento']])}<div class="section"><h3>Retiradas físicas</h3>${table(['Coleta','Data','Retirado (L)','Aceito (L)','Ação'],cs.map(c=>[c.id,date(c.date),fmt(c.liters),fmt(c.accepted),button('Ver coleta','collection-detail',c.id,'small')]),'Retiradas',true)}</div><div class="section"><h3>Qualidade associada</h3>${s.quality.length?table(['Amostra','Versão preservada','Ação'],s.quality.map(id=>[id,'v1 · snapshot comercial',button('Ver laudo','sample-detail',id,'small')]),'Laudos',true):'<p>Nenhuma amostra associada. Qualidade não é obrigatória para negociar preço.</p>'}</div><div class="section"><h3>Demonstrativos e comprovantes</h3>${s.docs.length?s.docs.map(d=>`<div class="fileline"><span>${esc(typeof d==='string'?d:d.name)}</span>${button('Consultar','commercial-document',s.id+'|'+(typeof d==='string'?d:d.name),'small')}</div>`).join(''):'<p>Nenhum documento nesta operação.</p>'}<div class="actions section">${button('Adicionar documento','sale-document',s.id)}${button('Conferir demonstrativo','statement',s.id)}</div></div><div class="section actions">${s.status==='Aberta'?button('Negociar preço e laudos','sale-price',s.id)+button('Fechar e gerar financeiro','sale-close',s.id,'primary'):s.status==='Fechada'?button('Consultar financeiro','finance-detail',s.id)+button('Corrigir condições comerciais','sale-correct',s.id)+button('Reenviar fechamento','sale-retry',s.id):''}</div>${s.status==='Fechada'?'<p class="section">Preço, aceite e documentos desta versão permanecem no histórico. O recebimento não cria outra baixa física.</p>':''}`);}
function salePrice(id,correct=false){if(state.hidden)return toast('Negociação de preço exige permissão para visualizar e registrar valores.');const s=state.sales.find(s=>s.id===id),samples=state.samples.filter(a=>a.date>=s.start&&a.date<=s.end&&a.status!=='Anulada');modal(correct?'Corrigir condições · '+id:'Negociar preço · '+id,`<div class="fields">${input('price','Preço por litro (R$)',s.price??'','number','step="0.0001" min="0.0001" required')}${select('financial','Condição financeira',['A receber','Receber agora'],'A receber')}<label class="full">Motivo / referência do acordo<textarea name="reason" required></textarea></label></div><div class="section"><h3>Laudos associados — opcionais</h3><div class="origins">${samples.map(a=>`<label class="origin"><input type="checkbox" name="quality" value="${a.id}" ${s.quality.includes(a.id)?'checked':''}><strong>${a.id} · ${a.subject}</strong><span>${date(a.date)} · v${a.version}</span></label>`).join('')}</div></div>${correct?'<div class="notice">Nova versão conserva a retirada física. Compromissos anteriores serão substituídos. Recebimentos confirmados exigiriam regularização no Financeiro.</div>':''}`, (v,form)=>{s.price=Number(v.price);s.quality=new FormData(form).getAll('quality');if(correct){s.version++;s.finance='FIN-'+s.id+'-v'+s.version;state.revisionLog.push({date:TODAY,version:s.version,reason:'Correção comercial '+id+': '+v.reason});}render();saleDetail(id);toast(correct?'Nova versão comercial criada; estoque preservado.':'Preço e laudos atualizados. A operação continua aberta.');},correct?'Confirmar nova versão':'Salvar negociação');}
function saleClose(id){const s=state.sales.find(s=>s.id===id);if(s.status==='Fechada')return toast('Fechamento recuperado: '+s.finance+'. Nenhuma nova operação ou baixa criada.');if(s.price===null)return salePrice(id);if(saleLiters(s)<=0)return toast('Registre uma retirada antes de fechar esta operação.');modal('Fechar operação '+id,`${lines([['Comprador',s.buyer],['Quantidade comercial',fmt(saleLiters(s,true))+' L'],['Preço por litro',money(s.price)],['Total',money(saleLiters(s,true)*s.price)],['Laudos associados',s.quality.join(', ')||'Nenhum']])}<div class="fields section">${input('due','Vencimento','2026-11-05','date','required')}${select('condition','Recebimento',['A receber','Receber agora'],'A receber')}</div><div class="notice">O financeiro será gerado uma vez. As retiradas já baixaram o estoque; o fechamento não baixa novamente.</div>${check('confirmed','Conferi o aceite, o preço e as condições financeiras.')}`,v=>{if(!v.confirmed)return fail('Confirme a conferência do fechamento.');if(s.status==='Fechada')return toast('Fechamento já concluído. Resultado existente recuperado.');s.status='Fechada';s.finance='FIN-'+s.id+'-v'+s.version;s.accepted=true;state.collections.filter(c=>c.op===id).forEach(c=>c.status='Preço definido');s.due=v.due;s.condition=v.condition;render();toast('Operação fechada. Financeiro '+s.finance+' criado uma vez.');},'Fechar operação');}
function newSale(){if(state.hidden)return toast('Venda avulsa exige permissão financeira para valores e lançamento.');modal('Venda avulsa de leite',`<div class="fields">${input('buyer','Comprador','','text','required')}${input('date','Data da retirada',TODAY,'date','required')}${input('liters','Volume retirado (L)','','number','step="0.001" min="0.001" required')}${input('price','Preço definitivo por litro (R$)','','number','step="0.0001" min="0.0001" required')}${select('condition','Condição financeira',['A receber','Receber agora'],'A receber')}${input('document','Referência documental','','text','required')}</div><div class="notice">Uma retirada física e uma operação financeira, criadas juntas. Somente origens comerciais conhecidas.</div>`,v=>{const liters=Number(v.liters),available=state.origins.filter(o=>o.nature==='Comercial').reduce((s,o)=>s+o.remaining,0);if(liters>available)return fail('Saldo comercial insuficiente. Disponível conhecido: '+fmt(available)+' L.');const portions=allocate(liters,'Comercial');const id='V'+(++state.next);state.sales.unshift({id,buyer:v.buyer,start:v.date,end:v.date,kind:'Avulsa',status:'Fechada',price:Number(v.price),liters,origins:portions,quality:[],docs:[v.document],finance:'FIN-'+id,accepted:true,version:1});render();toast('Venda avulsa registrada com uma única baixa física.');},'Confirmar venda avulsa');}
function saleDocument(id){modal('Adicionar documento · '+id,`<div class="fields">${select('kind','Tipo de documento',['Demonstrativo','Romaneio','Comprovante de pagamento','Acordo comercial'],'Demonstrativo')}${input('file','Selecionar arquivo','','file','accept=".pdf,.png,.jpg,.csv" required')}${input('ref','Referência / observação','','text','required')}</div><p class="section">Prévia local: só o nome do arquivo será guardado em memória. O arquivo não será lido ou enviado.</p>`,(v,form)=>{const file=form.elements.file.files[0];if(!file)return fail('Selecione um arquivo.');state.sales.find(s=>s.id===id).docs.push({name:file.name,kind:v.kind,reference:v.ref});render();toast('Referência do documento adicionada nesta sessão.');},'Guardar referência');}
function statement(id){if(state.hidden)return toast('Demonstrativo exige permissão financeira para valores.');const s=state.sales.find(s=>s.id===id);modal('Conferir demonstrativo · '+id,`<div class="fields">${input('base','Preço-base (R$/L)',s.price??'','number','step="0.0001" min="0" required')}${input('bonus','Bônus documentado (R$)',0,'number','step="0.01" min="0"')}${input('discount','Desconto documentado (R$)',0,'number','step="0.01" min="0"')}${input('retention','Retenção / adiantamento (R$)',0,'number','step="0.01" min="0"')}${input('reference','Referência do demonstrativo','','text','required')}${check('accept','Aceite conferido com o comprador',s.accepted)}</div><p class="section">Conferência documental por parcelas explícitas. Não calcula uma política de qualidade nem cria outra operação financeira.</p>`,v=>{if(state.hidden)return fail('Demonstrativo com valores exige permissão financeira.');s.docs.push({name:v.reference,kind:'Demonstrativo',base:Number(v.base),bonus:Number(v.bonus),discount:Number(v.discount),retention:Number(v.retention)});s.accepted=!!v.accept;render();toast('Demonstrativo conferido e associado à operação.');},'Guardar demonstrativo');}
function financeDetail(id){const s=state.sales.find(s=>s.id===id);modal('Financeiro · '+s.finance,`${lines([['Origem',s.id+' · '+s.buyer],['Valor',money(saleLiters(s,true)*s.price)],['Condição',s.condition||'A receber'],['Vencimento',date(s.due||'2026-11-05')],['Estado',s.received?'Recebimento confirmado':'Compromisso gerado'],['Baixa de estoque','Já vinculada às retiradas']])}<div class="section">${s.received?'':button('Simular recebimento','receive-sale',s.id)}</div><p class="section">O recebimento é um fato financeiro posterior e conserva o mesmo volume físico.</p>`);}
function sampleDetail(id){const s=state.samples.find(s=>s.id===id);if(!s)return toast('Amostra não encontrada.');modal('Amostra '+s.id+' · '+s.subject,`${lines([['Situação',badge(s.status)],['Tipo de amostra',s.kind],['Data da amostra',date(s.date)],['Resultado laboratorial',date(s.resultDate)],['Recebimento do laudo',date(s.received)],['Cadastro no sistema',date(s.created)],['Formato e versão',esc(s.format)+' · v1'],['Versão da amostra','v'+s.version],['Método informado',esc(s.method)]])}<div class="section"><h3>Laudo completo</h3>${Object.keys(s.values).length?table(['Parâmetro','Código','Resultado','Unidade'],state.parameters.filter(p=>s.values[p.id]!=null).map(p=>[esc(p.name),esc(p.id),fmt(s.values[p.id]),esc(p.unit)]),'Parâmetros',true):'<div class="notice">Coleta registrada. Resultados ainda não recebidos; não equivalem a zero.</div>'}</div><div class="section"><h3>Observações e arquivos</h3><p>${esc(s.notes||'Sem observações.')}</p>${s.files.map(f=>`<div class="fileline"><span>${esc(f)}</span>${button('Consultar referência','quality-document',s.id,'small')}</div>`).join('')}</div><div class="section"><h3>Histórico de versões</h3>${s.history.length?s.history.map(h=>`<p>${esc(h)}</p>`).join(''):'<p>Versão inicial conservada.</p>'}</div><div class="actions section">${s.status!=='Anulada'?button(s.status==='Aguardando resultado'?'Registrar resultado':'Corrigir laudo','edit-sample',s.id)+button('Anular amostra','annul-sample',s.id):''}${s.animal?button('Abrir ficha animal','animal',s.animal):''}</div><p class="section">Laudos coletivos não atribuem resultados automaticamente aos animais. Snapshots comerciais anteriores permanecem preservados.</p>`);}
function sampleForm(id){const existing=state.samples.find(s=>s.id===id);const s=existing||{date:TODAY,kind:'Coletiva',subject:'Tanque principal',format:state.formats[0].name,resultDate:'',received:'',values:{},method:'Infravermelho / citometria',notes:''};modal(existing?'Registrar / corrigir laudo · '+id:'Registrar amostra',`<div class="fields">${select('kind','Tipo de amostra',['Coletiva','Individual'],s.kind,'data-sample-kind')}${select('subject','Origem',s.kind==='Individual'?animals.map(a=>[`${a.id} · ${a.name}`,`${a.id} · ${a.name}`]):state.tanks.map(t=>t.name),s.subject,'data-sample-subject')}${input('date','Data da amostra',s.date,'date','required')}${select('format','Formato do laudo',state.formats.map(f=>f.name),s.format)}${input('resultDate','Data do resultado laboratorial',s.resultDate,'date')}${input('received','Data do recebimento do laudo',s.received,'date')}${input('method','Método informado no laudo',s.method,'text')}<label>Arquivo do laudo — opcional<input type="file" name="file" accept=".pdf,.jpg,.png"></label><label class="full">Observações<textarea name="notes">${esc(s.notes)}</textarea></label></div><div class="section"><h3>Resultados — opcionais no registro da coleta</h3><p>Preencha conforme o formato e as unidades do documento.</p><div class="fields section" id="sample-results">${resultFields(s.format,s.values)}</div></div>${existing?'<label class="field section">Motivo da correção / registro<textarea name="reason" required></textarea></label>':''}`,(v,form)=>{const values={};for(const p of state.parameters){const field=form.elements['param_'+p.id];if(field&&field.value!=='')values[p.id]=Number(field.value);}if(existing?.status==='Com resultado'&&!Object.keys(values).length)return fail('Uma lista vazia não apaga o laudo. Preserve os resultados ou corrija campos explicitamente.');let a=existing;if(!a){a={id:'A'+(++state.next),created:TODAY,version:0,files:[],history:[]};state.samples.unshift(a);}if(existing)a.history.push(`Versão ${a.version}: ${Object.entries(a.values).map(([k,n])=>k+' '+n).join(', ')||'coleta sem resultados'} · motivo: ${v.reason}`);Object.assign(a,{date:v.date,kind:v.kind,subject:v.subject,animal:v.kind==='Individual'?v.subject.split(' ')[0]:undefined,format:v.format,resultDate:v.resultDate,received:v.received,method:v.method||'Não informado',notes:v.notes,values,status:Object.keys(values).length?'Com resultado':'Aguardando resultado',version:a.version+1});const f=form.elements.file.files[0];if(f)a.files.push(f.name);render();toast(existing?'Nova versão do laudo registrada; histórico preservado.':'Amostra registrada de forma independente da venda.');},existing?'Salvar nova versão':'Registrar amostra');}
function resultFields(format,values={}){const f=state.formats.find(f=>f.name===format)||state.formats[0];return f.fields.map(id=>{const p=state.parameters.find(p=>p.id===id);return input('param_'+id,p.name+' ('+p.unit+')',values[id]??'','number','min="0" step="0.001"');}).join('');}
function formats(){modal('Formatos de laudo',`${table(['Formato','Versão','Método','Campos','Ação'],state.formats.map((f,i)=>[esc(f.name),'v'+f.version,esc(f.method),String(f.fields.length),button('Ver formato','format-detail',i,'small')]),'Formatos',true)}<div class="section">${button('Criar formato','new-format','','primary')}</div>`);}
function formatDetail(index){const f=state.formats[Number(index)];modal('Formato · '+f.name,`${lines([['Versão','v'+f.version],['Método',esc(f.method)]])}<div class="section">${table(['Código','Campo','Tipo','Unidade'],f.fields.map(id=>{const p=state.parameters.find(p=>p.id===id);return [esc(p.id),esc(p.name),'Número',esc(p.unit)];}),'Campos',true)}</div><p class="section">Os formatos são versionados. Unidade e método permanecem no laudo; rótulos iguais não tornam métodos equivalentes.</p><div class="section">${button('Criar nova versão','new-format',index)}</div>`);}
function newFormat(index){const f=index!==undefined&&index!==''?state.formats[Number(index)]:null;modal(f?'Nova versão de formato':'Criar formato de laudo',`<div class="fields">${input('name','Nome do formato',f?.name||'','text','required')}${input('method','Método do laudo',f?.method||'','text','required')}${input('code','Código de campo adicional — opcional','','text')}${input('label','Rótulo do campo adicional','','text')}${input('unit','Unidade do campo adicional','','text')}${select('type','Tipo do campo adicional',['Número'],'Número')}</div><div class="section"><h3>Campos do formato</h3><div class="origins">${state.parameters.map(p=>check('parameter',`${p.name} · ${p.unit}`,f?f.fields.includes(p.id):true,p.id)).join('')}</div></div>`,(v,form)=>{const fields=new FormData(form).getAll('parameter');if(v.code){if(!/^[a-z][a-z0-9_]*$/.test(v.code))return fail('Use um código único com letras minúsculas, números e sublinhado.');if(!v.label||!v.unit)return fail('Informe rótulo e unidade do campo adicional.');if(state.parameters.some(p=>p.id===v.code))return fail('Código já existente. Selecione o campo da lista.');state.parameters.push({id:v.code,name:v.label,unit:v.unit});fields.push(v.code);}if(!fields.length)return fail('Selecione pelo menos um campo.');state.formats.push({name:f?v.name+' · v'+(f.version+1):v.name,version:f?f.version+1:1,method:v.method,fields});render();toast('Formato versionado criado sem alterar laudos anteriores.');},'Salvar formato');}
function annulSample(id){const s=state.samples.find(s=>s.id===id);modal('Anular amostra '+id,'<label class="field">Motivo da anulação<textarea name="reason" required></textarea></label><div class="notice">O histórico e os snapshots de fechamentos anteriores serão preservados.</div>',v=>{s.history.push('Versão '+s.version+' anulada: '+v.reason);s.version++;s.status='Anulada';render();toast('Amostra anulada com histórico preservado.');},'Confirmar anulação');}
function feedForm(){modal('Registrar fornecimento de leite',`<div class="fields">${input('date','Data do fornecimento',TODAY,'date','required')}${select('kind','Tipo de fornecimento',['Alimentação','Colostragem'],'Alimentação','data-feed-kind')}${select('destination','Destino',['Bezerreiro · lote B01','Lactentes · lote B02'],'Bezerreiro · lote B01')}${select('condition','Condição informada',['Quente limpo','Quente sujo','Resfriado'],'Quente limpo')}<div class="full" id="calf-fields" hidden>${select('calf','Cria e parto comprovados',[['501','501 · parto P088 · Canela · 24/10/2026']],'501')}${select('colostrum-link','Fornecimento de colostro',[['new','Criar junto com esta destinação'],['FC031','Vincular FC031 · 4 L · cria 501 · 24/10/2026']],'new')}</div></div><div class="section"><h3>Origens e volumes efetivos</h3><p>Leite Descarte tem prioridade na alimentação; Comercial pode complementar. Colostro fica no fornecimento próprio da cria.</p>${table(['Origem','Natureza','Disponível (L)','Fornecer (L)'],state.origins.filter(o=>o.remaining>0&&!!o.nature).map(o=>[o.id,badge(o.nature),fmt(o.remaining),`<input type="number" name="qty_${o.id}" min="0" max="${o.remaining}" step="0.001" value="0" style="width:100px" aria-label="Fornecer da origem ${o.id} em litros">`]),'Origens',true)}</div><label class="field section">Receita / justificativa<textarea name="reason" required>Receita Aleitamento · v3 · 10 crias</textarea></label><div class="notice">R07: referência provisória de setembro ${state.hidden?'(valores ocultos)':'R$ 2,50/L'}. Pode ser revisada com fechamento do mês do consumo ou do anterior. Não é custo produtivo.</div>`,(v,form)=>{const portions=[];for(const o of state.origins){const qty=Number(form.elements['qty_'+o.id]?.value||0);if(!Number.isFinite(qty)||qty<0||qty>o.remaining)return fail('Confira a quantidade da origem '+o.id+'.');if(qty>0){if(v.kind==='Colostragem'&&o.nature!=='Colostro')return fail('Colostragem usa apenas origens de colostro.');if(v.kind==='Alimentação'&&o.nature==='Colostro')return fail('Selecione Colostragem para usar colostro e vincular a cria.');portions.push({id:o.id,liters:qty});}}const liters=portions.reduce((s,p)=>s+p.liters,0);if(!liters)return fail('Informe o volume efetivamente fornecido em pelo menos uma origem.');if(v.kind==='Colostragem'&&v['colostrum-link']==='FC031'&&Math.abs(liters-4)>.00001)return fail('O fornecimento existente FC031 comprova 4 L. Para outro volume, crie o vínculo junto com esta destinação.');for(const p of portions)state.origins.find(o=>o.id===p.id).remaining-=p.liters;const id='D'+(++state.next),origins=portions.map(p=>state.origins.find(o=>o.id===p.id));state.destinations.unshift({id,date:v.date,kind:v.kind,nature:[...new Set(origins.map(o=>o.nature))].join(' + '),liters,destination:v.kind==='Colostragem'?'Cria 501 · parto P088':v.destination,condition:v.condition,origins:portions,reference:v.kind==='Alimentação'?2.5:null,refVersion:1,refStatus:v.kind==='Alimentação'?'Provisória':'Não se aplica',cost:origins.every(o=>o.cost!==null)?portions.reduce((s,p)=>s+p.liters*state.origins.find(o=>o.id===p.id).cost,0):null,reason:v.kind==='Colostragem'?'Fornecimento '+(v['colostrum-link']==='new'?'FC'+state.next:v['colostrum-link'])+' · '+v.reason:v.reason,status:'Confirmado'});render();toast('Fornecimento confirmado com uma única baixa por origem.');},'Confirmar fornecimento');}
function discardForm(){modal('Registrar descarte físico',`<div class="fields">${input('date','Data do descarte',TODAY,'date','required')}${select('origin','Origem',state.origins.filter(o=>o.remaining>0).map(o=>[o.id,`${o.id} · ${o.nature} · ${fmt(o.remaining)} L`]),'O102','required')}${input('liters','Quantidade eliminada (L)','','number','step="0.001" min="0.001" required')}<label>Motivo<textarea name="reason" required></textarea></label></div><div class="notice">Descarte físico elimina o volume. Leite de natureza Descarte ainda disponível pode ter destino de alimentação; este comando registra eliminação.</div>${check('confirm','Confirmo a eliminação física desta quantidade.')}`,v=>{const o=state.origins.find(o=>o.id===v.origin),qty=Number(v.liters);if(!v.confirm)return fail('Confirme que a eliminação física ocorreu.');if(!o||qty>o.remaining)return fail('Quantidade maior que o saldo da origem.');o.remaining-=qty;state.destinations.unshift({id:'D'+(++state.next),date:v.date,kind:'Descarte físico',nature:o.nature,liters:qty,destination:'Eliminação física',condition:'Não se aplica',origins:[{id:o.id,liters:qty}],reference:null,refVersion:0,refStatus:'Não se aplica',cost:o.cost===null?null:o.cost*qty,reason:v.reason,status:'Confirmado'});render();toast('Descarte físico confirmado. Volume removido uma vez.');},'Confirmar descarte físico');}
function destinationDetail(id){const d=state.destinations.find(d=>d.id===id);modal(d.kind+' · '+id,`${lines([['Data',date(d.date)],['Destino',esc(d.destination)],['Natureza',esc(d.nature)],['Volume fornecido / eliminado',fmt(d.liters)+' L'],['Condição informada',esc(d.condition)],['Situação',badge(d.status)],['Referência / justificativa',esc(d.reason)]])}<div class="section"><h3>Origens utilizadas</h3>${table(['Origem','Natureza','Quantidade (L)'],d.origins.map(p=>[p.id,state.origins.find(o=>o.id===p.id)?.nature||'Histórica',fmt(p.liters)]),'Parcelas',true)}</div>${d.kind==='Alimentação'?`<div class="section"><h3>Referência gerencial R07</h3>${lines([['Preço comercial de referência',money(d.reference)+'/L'],['Total referencial',d.reference===null?money(null):money(d.liters*d.reference)],['Fonte',d.refSource||'V025 · setembro de 2026 · v1'],['Situação',badge(d.refStatus)],['Versão da referência','v'+d.refVersion],['Custo produtivo separado',money(d.cost)]])}<p class="section">Revisar a referência não altera litros, movimentos ou custo produtivo. O total referencial não se soma ao custo da fazenda.</p><div class="actions section">${button('Revisar referência','reference-review',id)}${button('Abrir Nutrição','goto','nutricao')}</div></div>`:''}${d.kind==='Colostragem'?'<div class="notice ok">Cria e parto comprovados. O destino cria ou vincula o FornecimentoColostro na mesma confirmação, sem duplicá-lo.</div>':''}<div class="actions section">${d.status==='Confirmado'?button('Estornar fornecimento / descarte','destination-reverse',d.id):''}</div>`);}
function referenceReview(id){if(state.hidden)return toast('Revisão R07 exige permissão financeira para valores e lançamento.');const d=state.destinations.find(d=>d.id===id),eligible=state.sales.filter(s=>s.status==='Fechada'&&s.price!==null&&['2026-09','2026-10'].includes(s.start.slice(0,7)));modal('Revisar referência gerencial R07',`<div class="fields">${select('source','Fechamento comercial comprovado',eligible.map(s=>[s.id,`${s.id} · ${s.buyer} · ${date(s.start)} a ${date(s.end)} · R$ ${fmt(s.price,2)}/L`]),'V025','required')}${select('period','Período do consumo',['Outubro de 2026 · aberto'],'Outubro de 2026 · aberto')}<label class="full">Motivo<textarea name="reason" required></textarea></label></div>${lines([['Referência atual',money(d.reference)+'/L'],['Total atual',money(d.liters*d.reference)],['Custo produtivo preservado',money(d.cost)]])}<div class="notice">Somente mês do consumo ou anterior e períodos abertos. Não calcula média entre compradores.</div>`,v=>{const s=state.sales.find(s=>s.id===v.source);if(!s)return fail('Selecione uma fonte comprovada.');d.reference=s.price;d.refSource=s.id+' · '+date(s.start)+' a '+date(s.end)+' · v'+s.version;d.refVersion++;d.refStatus='Revisada';d.refReason=v.reason;render();toast('Referência R07 revisada. Quantidade e custo produtivo preservados.');},'Confirmar revisão');}
function reverseDestination(id){const d=state.destinations.find(d=>d.id===id);modal('Estornar destinação '+id,'<label class="field">Motivo<textarea name="reason" required></textarea></label><div class="notice">O inverso recompõe as origens exatas uma vez. A natureza restrita permanece; o fato original continua no histórico.</div>',v=>{if(d.status==='Estornado')return toast('Estorno já registrado. Nenhuma quantidade foi duplicada.');d.origins.forEach(p=>state.origins.find(o=>o.id===p.id).remaining+=p.liters);d.status='Estornado';d.reverseReason=v.reason;render();toast('Estorno confirmado com recomposição das origens exatas.');},'Confirmar estorno');}
function versionConfig(reason,dateValue){state.config.version++;state.config.effective=dateValue;state.configHistory.push(Object.freeze({...JSON.parse(JSON.stringify(state.config)),reason,author:'Equipe Rio Novo'}));}
function configTurns(){modal('Configurar ordenhas',`<div class="fields">${input('count','Quantidade de ordenhas',state.config.turns.length,'number','min="1" max="6" required data-turn-count')}${input('effective','Vigência da nova configuração',TODAY,'date','min="2026-10-24" required')}</div><div class="fields section" id="turn-name-fields">${state.config.turns.map((t,i)=>input('turn'+i,'Nome da ordenha '+(i+1),t,'text','required')).join('')}</div><div class="notice">O nome e a posição ficam congelados nos registros históricos. A nova vigência não altera aferições anteriores.</div>`,v=>{const n=Number(v.count);if(n<1||n>6)return fail('Escolha entre uma e seis ordenhas.');const names=Array.from({length:n},(_,i)=>v['turn'+i]?.trim());if(names.some(n=>!n)||new Set(names).size!==names.length)return fail('Informe nomes distintos para todas as ordenhas.');state.config.turns=names;versionConfig('Ordenhas: '+names.join(', '),v.effective);render();toast('Nova versão de ordenhas guardada; histórico preservado.');},'Salvar nova vigência');}
function configIndividual(){modal('Controle individual e fonte de produção',`<div class="fields">${input('interval','Intervalo entre controles',state.config.interval,'number','min="1" required')}${select('unit','Unidade do intervalo',['Dias','Meses'],state.config.intervalUnit)}${select('source','Fonte da produção geral',['Geral','Individual'],state.config.source)}${input('effective','Vigência',TODAY,'date','min="2026-10-24" required')}</div><div class="notice">Geral e Individual são fontes alternativas. O controle individual mensal permanece consultável sem somar de novo ao volume do tanque.</div>`,v=>{state.config.interval=Number(v.interval);state.config.intervalUnit=v.unit;state.config.source=v.source;versionConfig('Controle individual: '+v.interval+' '+v.unit+' · fonte '+v.source,v.effective);render();toast('Fonte e intervalo registrados com nova vigência.');},'Salvar nova vigência');}
function configColostrum(){const c=state.config;modal('Critério de colostro',`<fieldset><legend>Escolha um critério</legend><label class="origin"><input type="radio" name="criterion" value="primeira" ${c.colostrum==='primeira'?'checked':''}><strong>Primeira ordenha após o parto</strong></label><p>Exige comprovação ou declaração explícita por vaca. O tanque e o controle mensal não comprovam a primeira ordenha.</p><label class="origin"><input type="radio" name="criterion" value="janela" ${c.colostrum==='janela'?'checked':''}><strong>Janela pós-parto em dias</strong></label></fieldset><div class="fields">${input('days','Dias da janela',c.days,'number','min="1" max="30" required')}${input('effective','Vigência da regra',TODAY,'date','min="2026-10-24" required')}</div><div class="section"><h3>Exemplos no dia do parto</h3>${table(['Evidência','Tratamento'],[['Canela · parto P088 hoje · DEL 0','Origem específica selecionável; não entra na seleção geral DEL > 0'],['Primeira ordenha comprovada','Colostro · primeira ordenha'],['Ordenha posterior na janela configurada','Leite de transição · natureza operacional Colostro'],['Histórico sem parto ou regra comprovada','Classificação pendente; sem preenchimento presumido']],'Exemplos',true)}<p class="section">Janela de N dias: DEL 0 até N−1 na data civil da fazenda; com 3 dias inclui o dia do parto e os dois seguintes. Fora da janela, elegibilidade comercial continua a exigir conferência própria.</p></div><label class="field section">Motivo da nova regra<textarea name="reason" required></textarea></label>`,v=>{c.colostrum=v.criterion;c.days=Number(v.days);versionConfig((v.criterion==='primeira'?'Primeira ordenha comprovada':'Janela pós-parto '+v.days+' dias')+' · '+v.reason,v.effective);render();toast('Regra versionada. Histórico não reclassificado.');},'Salvar nova regra');}
function tankDetail(id){const t=state.tanks.find(t=>t.id===id);modal(t.name,`${lines([['Capacidade',fmt(t.capacity,0)+' L'],['Fabricante',esc(t.brand)],['Modelo',esc(t.model)],['Série',esc(t.serial)],['Vigência',date(t.effective)],['Versão',String(t.version)],['Referência documental',esc(t.reference)]])}<div class="section">${table(['mm','Litros exatos'],Object.entries(t.points).map(([mm,l])=>[mm,fmt(l)]),'Pontos',true)}</div><div class="actions section">${button('Criar nova versão','edit-tank',t.id)}</div>`);}
function tankForm(id){const t=state.tanks.find(t=>t.id===id);modal(t?'Nova versão do tanque':'Cadastrar tanque',`<div class="fields">${input('name','Nome',t?.name||'','text','required')}${input('capacity','Capacidade nominal (L)',t?.capacity||'','number','min="1" required')}${input('brand','Fabricante',t?.brand||'','text','required')}${input('model','Modelo',t?.model||'','text','required')}${input('serial','Número de série',t?.serial||'','text','required')}${input('effective','Vigência',TODAY,'date','min="2026-10-24" required')}${input('reference','Referência documental',t?.reference||'','text','required')}<label class="full">Tabela de calibração · um ponto mm;litros por linha<textarea name="points" placeholder="100;336,7&#10;200;650,8">${t?Object.entries(t.points).map(([mm,l])=>mm+';'+String(l).replace('.',',')).join('\n'):''}</textarea></label></div><p class="section">Sem tabela, somente litros medidos diretamente. Nova versão conserva o equipamento e as medições anteriores.</p>`,v=>{const points={};for(const line of v.points.split('\n').filter(l=>l.trim())){const [mm,l]=line.split(';');const m=Number(mm?.trim()),n=Number(l?.trim().replace(',','.'));if(!Number.isFinite(m)||!Number.isFinite(n)||m<0||n<0)return fail('Use mm;litros em cada linha, sem valores negativos.');if(points[m]!==undefined)return fail('Há dois volumes para o mesmo ponto em mm.');points[m]=n;}if(t){state.revisionLog.push({date:v.effective,version:t.version,reason:'Calibração anterior de '+t.name+' preservada no snapshot'});state.tanks.push({...t,id:t.id+'v'+(t.version+1),name:v.name+' · v'+(t.version+1),capacity:Number(v.capacity),brand:v.brand,model:v.model,serial:v.serial,effective:v.effective,reference:v.reference,points,version:t.version+1});}else state.tanks.push({id:'t'+(++state.next),name:v.name,capacity:Number(v.capacity),brand:v.brand,model:v.model,serial:v.serial,effective:v.effective,reference:v.reference,points,version:1});render();toast('Versão do tanque guardada sem alterar calibrações históricas.');},t?'Salvar nova versão':'Cadastrar tanque');}
function includeAnimal(){modal('Incluir animal no controle individual',`<div class="fields">${select('animal','Animal disponível',animals.filter(a=>!state.individual[a.id]).map(a=>[a.id,a.id+' · '+a.name+(a.del===0?' · DEL 0':' · lactação não comprovada')]),'422')}${input('reason','Motivo da inclusão','','text','required')}${check('unknown','Registrar com pendência de lactação quando não comprovada',false)}</div><p class="section">A inclusão exige finalidade Leite e localização na data. Não cria lactação ou litros fictícios.</p>`,v=>{const a=animals.find(a=>a.id===v.animal);if(!a)return fail('Escolha um animal.');if(a.del===null&&!v.unknown)return fail('Confirme explicitamente a pendência de lactação.');state.individual[a.id]=[null,null,null];state.individualSaved=false;render();toast('Animal incluído no rascunho com motivo preservado.');});}
function saveIndividual(){if(!Object.values(state.individual).every(values=>values.every(v=>v===null||v===''||Number.isFinite(Number(v))&&Number(v)>=0)))return toast('Confira os volumes do controle individual.');state.individualSaved=true;toast('Controle individual salvo; produção geral e estoque preservados.');}
function confirmIndividual(){if(state.config.source==='Geral')return modal('Fonte de produção vigente',`<p>O controle individual foi preservado. A fonte de produção é Geral; a entrada desta rotina vem da aferição do tanque.</p><div class="section">${button('Abrir aferição geral','goto','ordenhas')}${button('Consultar configuração da fonte','goto','configuracoes')}</div>`);if(state.indConfirm)return toast('Confirmação individual existente recuperada, sem nova entrada.');modal('Conferir entrada individual',`${table(['Animal','Volume medido (L)','Natureza'],Object.entries(state.individual).map(([id,v])=>[id,fmt(v.reduce((s,n)=>s+Number(n||0),0)),`<select name="nature_${id}" aria-label="Natureza do animal ${id}"><option value="">Escolha</option><option>Comercial</option><option>Descarte</option><option>Colostro</option></select>`]),'Animais',true)}<div class="notice">Agrupamento por medições inteiras. Não soma ao tanque e não fraciona litros de uma vaca entre naturezas.</div>${check('confirmed','Conferi a distribuição e a separação física.')}`,v=>{if(!v.confirmed)return fail('Confirme a conferência.');for(const [id,values] of Object.entries(state.individual)){const liters=values.reduce((s,n)=>s+Number(n||0),0);if(liters>0&&!v['nature_'+id])return fail('Escolha a natureza de todos os animais com litros.');}for(const [id,values] of Object.entries(state.individual)){const liters=values.reduce((s,n)=>s+Number(n||0),0),nature=v['nature_'+id];if(liters>0)state.origins.push({id:'O'+(++state.next),date:TODAY,turn:'Controle individual',tank:'Não se aplica',product:nature==='Comercial'?'Leite resfriado':nature==='Colostro'?'Colostro':'Leite para uso interno',nature,qty:liters,remaining:liters,cost:null,animals:[id],status:'Confirmada'});}state.indConfirm=true;render();toast('Controle individual confirmado uma vez na fonte Individual.');},'Confirmar entrada individual');}
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;document.body.appendChild(a);a.click();const u=a.href;a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function reportForm(){if(state.hidden)return toast('Emissão de documento com valores exige permissão financeira.');modal('Emitir documento do leite',`<div class="fields">${select('kind','Relatório',['Produção','Estoque e origens','Qualidade','Comercial e custos'],'Produção')}${input('period','Período','Outubro de 2026','text','required')}${input('date','Data da emissão',TODAY,'date','required')}</div><p class="section">A emissão conserva um snapshot local imutável do recorte desta sessão. Não publica nem envia o documento.</p>`,v=>{state.snapshots.unshift({id:'R'+(++state.next),date:v.date,period:v.period,kind:v.kind,version:1,snapshot:JSON.parse(JSON.stringify({measurements:state.measurements,origins:state.origins,sales:state.sales,samples:state.samples}))});render();toast('Snapshot histórico emitido nesta sessão.');},'Emitir snapshot');}
function exportReport(kind){if(state.hidden&&kind==='comercial')return toast('Exportação comercial com valores exige permissão financeira.');const rows=kind==='producao'?[['Registro','Data','Ordenha','Natureza','Origem_fisica','Versao_tanque','Regua_mm','Litros_manuais','Estado'],...state.measurements.flatMap(m=>measureParts(m).map(p=>[m.id,m.date,m.turn,p.nature||'Classificação pendente',p.container,p.tankSnapshot?.version||'',p.mm,p.liters,m.status]))]:kind==='estoque'?[['Origem','Produto','Natureza','Remanescente_L'],...state.origins.map(o=>[o.id,o.product,o.nature,o.remaining])]:kind==='qualidade'?[['Amostra','Data','Origem','Parâmetro','Resultado','Unidade'],...state.samples.flatMap(s=>Object.entries(s.values).map(([id,v])=>[s.id,s.date,s.subject,id,v,state.parameters.find(p=>p.id===id)?.unit||'']))]:[['Operação','Comprador','Estado','Preço_L'],...state.sales.map(s=>[s.id,s.buyer,s.status,s.price??'Pendente'])];download('previa-leite-'+kind+'.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Exportação local gerada com dados fictícios.');}
function snapshotDetail(id){if(state.hidden)return toast('Documentos emitidos com valores exigem permissão financeira.');const s=state.snapshots.find(s=>s.id===id);modal('Documento '+id,`${lines([['Período',esc(s.period)],['Tipo',esc(s.kind)],['Emissão',date(s.date)],['Versão preservada','v'+s.version],['Situação','Snapshot imutável da emissão']])}<p class="section">Mudanças posteriores da sessão não reescrevem este documento.</p><div class="section">${button('Baixar snapshot local','snapshot-download',id)}</div>`);}
function importPreview(){const file=$('#import-form').elements.file.files[0];$('#import-preview').innerHTML=`<div class="sectionhead section"><h3>Conferência · ${esc(file?.name||'exemplo demonstrativo.csv')}</h3>${badge('Prévia sem gravação')}</div>${table(['Linha','Fato','Quantidade','Evidência','Situação'],[['2','Produção histórica','50,0 L','Natureza sem comprovação',badge('Classificação pendente')],['3','Amostra coletiva','CPP 42 mil UFC/mL','Formato e unidade conferidos',badge('Conferida')],['4','Parto / colostro','Vaca 422','Sem declaração da primeira ordenha',badge('Histórico pendente')]],'Linhas',true)}<div class="notice">1 linha conferida e 2 pendências. Nesta prévia não existe comando de gravar ou corrigir os fatos operacionais.</div><div class="actions">${button('Conferir linha histórica','history-review','H004')}${button('Baixar resumo da conferência','import-download')}</div>`;}
const actions={
 menu:()=>$('#sidebar').classList.toggle('open'),close:closeDialog,
 about:()=>modal('Sobre esta prévia','<p>Proposta navegável C01 para aprovação do plano V5. Todos os valores, animais e documentos são fictícios.</p><p>Os formulários alteram apenas a memória desta página. Recarregar descarta as simulações; nenhum serviço, banco, arquivo do projeto ou ambiente operacional é alterado.</p><p>Fluxos: ordenha → estoque → coleta → operação → financeiro; amostras independentes; alimentação e descarte com origens rastreáveis; configurações com vigência.</p>'),
 filters, 'clear-filter':id=>navigate(route.page,{[id]:null,pagina:null}),'reset-filters':()=>{$$('#modal-form select').forEach(s=>s.value=s.name==='modo'?'dia':'');},page:id=>navigate(route.page,{pagina:Math.max(1,Number(id))}),
 goto:id=>{closeDialog();navigate(id);},animal:id=>{closeDialog();navigate('animal',{id,modo:'producao'});},
 'expand-part':nature=>{captureDraft();const d=draft(),p=d.parts[nature],ctx=parcelContext(d);p.expanded=true;if(!partHasData(p))p.origins=nature==='Descarte'?ctx.withholding.map(a=>a.id):ctx.births.map(b=>b.animal);d.dirty=true;render();},'add-justified-part':()=>justifiedPartForm(),'new-register':()=>{closeDialog();navigate('ordenhas',{modo:'registro',medicao:null,rascunho:'R'+(++state.next),data:TODAY,turno:0});},'resume-register':key=>{navigate('ordenhas',key.startsWith('registro|')?{modo:'registro',medicao:key.slice(9),rascunho:null}:{modo:'registro',medicao:null,rascunho:key.slice(9)});},'back-orders':()=>{captureDraft();navigate('ordenhas',{modo:'geral'});toast('Consulta restaurada; rascunho preservado nesta sessão.');},'retry-measure':id=>{const count=state.origins.filter(o=>o.measureId===id).length;toast('Confirmação '+id+' recuperada. '+count+' entrada existente; nenhuma nova entrada criada.');},'save-measure':()=>saveMeasure(false),'confirm-measure':()=>saveMeasure(true),origins:originsModal,'tank-table':tankTable,'tank-detail':tankDetail,'edit-tank':tankForm,'new-tank':()=>tankForm(),
 'discard-and-change':id=>{const changes=JSON.parse(id);delete state.drafts[draftKey()];closeDialog();navigate('ordenhas',changes);},
 'production-detail':productionDetail,costs,'open-day':id=>{closeDialog();navigate('ordenhas',{modo:'geral',de:id,ate:id,medicao:null,rascunho:null});},
 'open-measure':id=>{const m=state.measurements.find(m=>m.id===id);closeDialog();navigate('ordenhas',{modo:'registro',medicao:id,rascunho:null,data:m.date,turno:Math.max(0,configAt(m.date).turns.indexOf(m.turn))});},
 'stock-detail':stockDetail,'origin-detail':originDetail,'value-origin':valueOrigin,'history-review':historyReview,
 'shared-stock':()=>modal('Movimentos do estoque compartilhado',`${table(['Fato','Tipo','Volume (L)','Rastreabilidade'],[...state.origins.map(o=>[o.id,'Entrada',fmt(o.qty),o.nature]),...state.collections.filter(c=>c.date>='2026-10-01').map(c=>[c.id,'Saída · coleta',fmt(c.liters),c.op]),...state.destinations.map(d=>[d.id,'Saída · '+d.kind,fmt(d.liters),d.origins.map(o=>o.id).join(', ')])],'Movimentos',true)}<p class="section">As rotinas consultam e movimentam a mesma base. Nenhuma cópia de saldo é criada para Leite.</p>`),
 'new-collection':newCollection,'collection-detail':collectionDetail,'collection-accept':collectionAccept,routine,
 'new-operation':newOperation,'new-sale':newSale,'sale-detail':saleDetail,'sale-price':id=>salePrice(id),'sale-close':saleClose,'sale-retry':saleClose,'sale-correct':id=>{const s=state.sales.find(s=>s.id===id);if(s.received)return toast('Recebimento confirmado: regularize no Financeiro antes de corrigir.');salePrice(id,true);},'sale-document':saleDocument,statement,
 'commercial-document':id=>{const [op,name]=id.split('|');modal('Documento comercial',lines([['Operação',esc(op)],['Arquivo / referência',esc(name)],['Conteúdo','Referência demonstrativa local'],['Estado','Nenhum arquivo foi enviado']])+`<div class="section">${button('Baixar resumo local','document-download',op)}</div>`);},
 'finance-detail':financeDetail,'receive-sale':id=>{if(state.hidden)return toast('Recebimento exige permissão financeira para valores e lançamento.');const s=state.sales.find(s=>s.id===id);s.received=true;closeDialog();toast('Recebimento financeiro simulado. Estoque e litros preservados.');},
 'new-sample':()=>sampleForm(),'sample-detail':sampleDetail,'edit-sample':sampleForm,'annul-sample':annulSample,formats,'format-detail':formatDetail,'new-format':newFormat,
 'quality-document':id=>{const s=state.samples.find(s=>s.id===id);modal('Referência do laudo '+id,lines([['Arquivo',esc(s.files.join(', '))],['Amostra',s.id],['Disponibilidade','Arquivo demonstrativo; nenhum conteúdo de laboratório anexado']])+`<div class="section">${button('Baixar laudo demonstrativo','sample-download',id)}</div>`);},
 'new-feed':feedForm,'new-discard':discardForm,'destination-detail':destinationDetail,'reference-review':referenceReview,'destination-reverse':reverseDestination,
 'config-turns':configTurns,'config-individual':configIndividual,'config-colostrum':configColostrum,
 'include-animal':includeAnimal,'save-individual':saveIndividual,'confirm-individual':confirmIndividual,
 'report-form':reportForm,'export-report':exportReport,'snapshot-detail':snapshotDetail,'snapshot-download':id=>{if(state.hidden)return toast('Snapshot com valores indisponível nesta permissão.');const s=state.snapshots.find(s=>s.id===id);download('previa-'+id+'.json',JSON.stringify(s,null,2));toast('Snapshot local baixado.');},
 'document-download':id=>state.hidden?toast('Documento com valores indisponível nesta permissão.'):download('demonstrativo-'+id+'.txt','DOCUMENTO DEMONSTRATIVO — SEM VALIDADE\n'+JSON.stringify(state.sales.find(s=>s.id===id),null,2),'text/plain'),
 'sample-download':id=>download('laudo-demonstrativo-'+id+'.json',JSON.stringify(state.samples.find(s=>s.id===id),null,2)),
 'import-preview':importPreview,'import-download':()=>{download('conferencia-demonstrativa.json',JSON.stringify({preview:true,writes:0,reviewed:1,pending:2},null,2));toast('Resumo da conferência baixado.');},
 scenario:id=>{state.hidden=id==='ocultos';state.scenario=id==='historico'||id==='ocultos'?'normal':id;closeDialog();navigate(id==='historico'?'estoque':id==='ocultos'?'vendas':'producao');render();toast(id==='ocultos'?'Cenário com valores ocultos ativado.':id==='historico'?'Histórico pendente em destaque no estoque.':'Cenário ativado nesta prévia.');},
 recover:()=>{state.scenario='normal';state.hidden=false;render();toast('Consulta normal restaurada.');},
 'help-production':()=>modal('Leitura da produção','<p>Os turnos e o total somam somente os litros manuais das parcelas. A régua é registrada ao lado dos litros e não é convertida ou somada.</p><p>Dia ou mês é escolhido no painel Filtros. A tabela de custos abaixo usa o mesmo recorte; parcelas sem custo permanecem pendentes.</p>'),
 'help-stock':()=>modal('Saldo e disponibilidade','<p>Medições não confirmadas ficam fora do saldo. As origens confirmadas compartilham os mesmos movimentos de Estoque, Nutrição e Financeiro.</p><p>O total comercial identificado mostra apenas origens declaradas comerciais. Classificação histórica pendente impede afirmar uma disponibilidade completa.</p><p>O tanque de origem não prova onde está todo o saldo hoje. Custo pendente não significa volume zero.</p>')
};
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const fn=actions[el.dataset.action];if(fn)fn(el.dataset.id,event);});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='modal-form')saveModal(event.target);});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='query-search'){const pos=el.selectionStart;const params=new URLSearchParams(route.params);params.set('busca',el.value);params.delete('pagina');history.replaceState(null,'','#'+route.page+'?'+params);render();const e=$('#query-search');e.focus();e.setSelectionRange(pos,pos);return;}
 if(el.closest('#ordenha-form')){const d=draft();d.dirty=true;captureDraft();const total=$('#order-total');if(total)total.textContent=fmt(milkNatures.reduce((n,k)=>n+Number(d.parts[k].liters||0),0))+' L';}
 if(el.dataset.ind){state.individual[el.dataset.ind][Number(el.dataset.turn)]=el.value===''?null:Number(el.value);state.individualSaved=false;}
 if(el.matches('[data-turn-count]')){const n=Math.min(6,Math.max(1,Number(el.value)||1));const old=serialize($('#modal-form'));$('#turn-name-fields').innerHTML=Array.from({length:n},(_,i)=>input('turn'+i,'Nome da ordenha '+(i+1),old['turn'+i]||state.config.turns[i]||'','text','required')).join('');}
});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.query){navigate(route.page,{[el.dataset.query]:el.value,pagina:null});return;}if(el.matches('[data-part-tank]')){captureDraft();draft().dirty=true;render();return;}if(el.matches('[data-record-date]')){captureDraft();draft().dirty=true;render();return;}
 if(el.matches('[data-sample-kind]')){const subject=$('[data-sample-subject]');subject.innerHTML=(el.value==='Individual'?animals.map(a=>a.id+' · '+a.name):state.tanks.map(t=>t.name)).map(v=>`<option>${esc(v)}</option>`).join('');}
 if(el.name==='format'&&$('#sample-results'))$('#sample-results').innerHTML=resultFields(el.value);
 if(el.matches('[data-feed-kind]'))$('#calf-fields').hidden=el.value!=='Colostragem';
});
$('#dialog').addEventListener('cancel',event=>{event.preventDefault();closeDialog();});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
$$('aside nav a').forEach(a=>a.insertAdjacentHTML('afterbegin',icon(a.hash.slice(1))));
window.addEventListener('hashchange',()=>{if($('#ordenha-form'))captureDraft();render();});
render();
